local rows=game:GetService("HttpService"):JSONDecode([====[[{"path": ["ReplicatedStorage", "Shared", "WeatherVFXQuality"], "class": "ModuleScript", "source": "-- Cosmetic-only controls. Server weather state and audio never depend on these.\nlocal Players = game:GetService(\"Players\")\nlocal Quality = {}\nlocal SCALES = { Low = 0.35, Medium = 0.65, High = 1 }\nfunction Quality.Resolve()\n local player = Players.LocalPlayer\n local setting = player and player:GetAttribute(\"WeatherVFXQuality\")\n local scale = type(setting) == \"number\" and math.clamp(setting, 0.25, 1) or SCALES[setting] or 1\n local intensity = player and player:GetAttribute(\"WeatherEventIntensity\")\n intensity = type(intensity) == \"number\" and math.clamp(intensity, 0.35, 1) or 1\n return {qualityScale = scale, intensity = intensity}\nend\nreturn Quality\n"}, {"path": ["ReplicatedStorage", "Shared", "WeatherSoundDefinitions"], "class": "ModuleScript", "source": "-- Weather presentation only. Empty IDs are intentional upload/permission slots.\n-- Do not replace an empty slot with an invented Roblox asset ID.\nlocal Definitions = {}\n\nDefinitions.Mix = {\n\tMasterVolume = 0.72,\n\tFadeIn = 1.5,\n\tFadeOut = 1.2,\n\tMaxLoops = 3,\n\tMaxOneShots = 8,\n\tMaxVoices = 11,\n\tMaxPendingCues = 12,\n\tUpdateInterval = 0.2,\n}\n\nDefinitions.Assets = {\n\t-- These IDs were already configured in Animal Kingdom before this polish pass.\n\tExistingRain = { SoundId = \"rbxassetid://1516791621\", Description = \"Existing rain recording\" },\n\tExistingThunder = { SoundId = \"rbxassetid://12222030\", Description = \"Existing thunder recording\" },\n\tExistingWind = { SoundId = \"rbxassetid://8202539690\", Description = \"Existing wind recording\" },\n\tExistingEerieWind = { SoundId = \"rbxassetid://9114228918\", Description = \"Existing eerie wind recording\" },\n\tExistingMeteor = { SoundId = \"rbxassetid://9120705982\", Description = \"Existing meteor whoosh recording\" },\n\tExistingWaterSplash = { SoundId = \"rbxasset://sounds/impact_water.mp3\", Description = \"Roblox built-in splash verified in the live character\" },\n}\n\nlocal function slot(name, description, fallback)\n\tDefinitions.Assets[name] = { SoundId = \"\", Description = description, Fallback = fallback }\nend\n\nslot(\"DayAmbience\", \"Seamless peaceful daytime nature\", \"ExistingWind\")\nslot(\"Bird1\", \"Quiet daytime bird call variant 1\")\nslot(\"Bird2\", \"Quiet daytime bird call variant 2\")\nslot(\"WindGust1\", \"Broad wind gust variant 1\", \"ExistingWind\")\nslot(\"WindGust2\", \"Broad wind gust variant 2\", \"ExistingWind\")\nslot(\"LeafRustle\", \"Gentle foliage rustling loop\")\nslot(\"RainDistant\", \"Soft distant rain loop\")\nslot(\"RainSplash1\", \"Small water splash variant 1\", \"ExistingWaterSplash\")\nslot(\"RainSplash2\", \"Small water splash variant 2\", \"ExistingWaterSplash\")\nslot(\"RainDrip1\", \"Gentle rain drip texture\")\nslot(\"ThunderClose1\", \"Close thunder crack variant 1\", \"ExistingThunder\")\nslot(\"ThunderClose2\", \"Close thunder crack variant 2\", \"ExistingThunder\")\nslot(\"ThunderDistant1\", \"Long rolling distant thunder variant 1\", \"ExistingThunder\")\nslot(\"ThunderDistant2\", \"Long rolling distant thunder variant 2\", \"ExistingThunder\")\nslot(\"WinterWind\", \"Cold soft wind loop\", \"ExistingWind\")\nslot(\"WinterAmbience\", \"Quiet muffled winter ambience loop\")\nslot(\"FogDrone\", \"Quiet mysterious fog drone loop\", \"ExistingEerieWind\")\nslot(\"DistantForestCue\", \"Sparse mysterious distant forest sound\")\nslot(\"DryWind\", \"Dry airy desert wind loop\", \"ExistingWind\")\nslot(\"HeatInsects\", \"Subtle hot-weather insects loop\")\nslot(\"AuroraPad\", \"Beautiful airy aurora pad loop\")\nslot(\"CrystalChime1\", \"Soft crystalline chime variant 1\")\nslot(\"CrystalChime2\", \"Soft crystalline chime variant 2\")\nslot(\"MagicShimmer\", \"Soft magical shimmer loop\")\nslot(\"AirySweep\", \"Airy magical sweep\")\nslot(\"BloodMoonAmbience\", \"Low ominous blood moon drone loop\", \"ExistingEerieWind\")\nslot(\"BloodMoonPulse\", \"Soft low blood moon pulse\")\nslot(\"DarkMagic\", \"Quiet dark magical texture\")\nslot(\"BloodMoonStart\", \"Short ominous activation swell\")\nslot(\"NightHowl\", \"Rare distant atmospheric howl\")\nslot(\"MeteorSkyRumble\", \"Quiet distant sky rumble loop\")\nslot(\"MeteorWhooshSmall1\", \"Small fiery meteor whoosh variant 1\", \"ExistingMeteor\")\nslot(\"MeteorWhooshSmall2\", \"Small fiery meteor whoosh variant 2\", \"ExistingMeteor\")\nslot(\"MeteorWhooshLarge1\", \"Large fiery meteor whoosh variant 1\", \"ExistingMeteor\")\nslot(\"MeteorWhooshLarge2\", \"Large fiery meteor whoosh variant 2\", \"ExistingMeteor\")\nslot(\"MeteorImpactSmall1\", \"Small meteor rock impact variant 1\", \"ExistingThunder\")\nslot(\"MeteorImpactSmall2\", \"Small meteor rock impact variant 2\", \"ExistingThunder\")\nslot(\"MeteorImpactLarge1\", \"Large low-end meteor impact variant 1\", \"ExistingThunder\")\nslot(\"MeteorImpactLarge2\", \"Large low-end meteor impact variant 2\", \"ExistingThunder\")\nslot(\"RockDebris\", \"Short scattering stone debris\")\nslot(\"FireCrackle\", \"Short seamless crackling fire loop\")\nslot(\"FireBurst\", \"Brief rushing fire burst\")\nslot(\"SpiritAmbience\", \"Airy ghostly spirit ambience loop\", \"ExistingEerieWind\")\nslot(\"SpiritWhisper1\", \"Sparse indistinct spirit whisper variant 1\")\nslot(\"SpiritWhisper2\", \"Sparse indistinct spirit whisper variant 2\")\nslot(\"SpiritChime\", \"Soft nearby spirit orb chime\")\nslot(\"SpiritSweep\", \"Ghost passing/reversed airy sweep\")\nslot(\"RainbowAmbience\", \"Pleasant magical rainbow ambience loop\")\nslot(\"RainbowStart\", \"Brief happy rainbow activation shimmer\")\nslot(\"ChaosWarp\", \"Soft shifting chaotic ambience loop\", \"ExistingEerieWind\")\nslot(\"MagicZap1\", \"Soft magical zap variant 1\")\nslot(\"MagicZap2\", \"Soft magical zap variant 2\")\nslot(\"InvertedAmbience\", \"Reversed-feeling surreal ambience loop\", \"ExistingEerieWind\")\nslot(\"ReverseSweep\", \"Gentle backwards-feeling tonal sweep\")\nslot(\"NightmareDrone\", \"Dark distant nightmare drone loop\", \"ExistingEerieWind\")\nslot(\"NightmarePulse\", \"Subtle heartbeat-like pulse\")\nslot(\"NightmareStinger\", \"Rare quiet distant nightmare stinger\")\nslot(\"VoidAmbience\", \"Deep cosmic space ambience loop\", \"ExistingEerieWind\")\nslot(\"CosmicRumble\", \"Gentle broad cosmic low rumble loop\")\nslot(\"CosmicEnergy1\", \"Purple cosmic energy crack variant 1\")\nslot(\"CosmicEnergy2\", \"Purple cosmic energy crack variant 2\")\nslot(\"CosmicTone\", \"Distant planet/space tonal swell\")\nslot(\"VoidStart\", \"Short cosmic opening swell\")\nslot(\"GoldenAmbience\", \"Warm treasure-like magical ambience loop\")\nslot(\"GoldenChime1\", \"Soft valuable golden chime variant 1\")\nslot(\"GoldenChime2\", \"Soft valuable golden chime variant 2\")\nslot(\"GoldenStart\", \"Short rewarding golden activation swell\")\nslot(\"AdminRealityBreak\", \"Short large reality-breaking activation cue\")\nslot(\"EventEnd\", \"Short gentle neutral weather exit cue\")\n\n-- Equalizers vary tone without large pitch shifts. Low/Mid/High are decibels.\nDefinitions.Tones = {\n\tNatural = { Low = -2, Mid = 0, High = -1 },\n\tSoft = { Low = -4, Mid = -3, High = -5 },\n\tCold = { Low = -6, Mid = -2, High = 1 },\n\tDry = { Low = -7, Mid = 0, High = -1 },\n\tDistant = { Low = 1, Mid = -3, High = -8 },\n\tOminous = { Low = 2, Mid = -3, High = -9 },\n\tDream = { Low = -4, Mid = -2, High = -5 },\n\tCosmic = { Low = 2, Mid = -4, High = -8 },\n\tBright = { Low = -5, Mid = -1, High = 1 },\n\tWarped = { Low = -2, Mid = -7, High = -2 },\n}\n\nlocal function layer(name, asset, volume, category, tone, cycle)\n\treturn { Name = name, Assets = { asset }, Volume = volume, Category = category or \"Ambience\", Tone = tone or \"Natural\", Cycle = cycle }\nend\nlocal function cue(assets, volume, category, minimum, maximum, duration, cooldown, tone)\n\treturn { Assets = assets, Volume = volume, Category = category, MinDistance = minimum,\n\t\tMaxDistance = maximum, Duration = duration or 10, Cooldown = cooldown or 1, Tone = tone or \"Natural\" }\nend\n\nDefinitions.Cues = {\n\tThunderStrike = cue({ \"ThunderClose1\", \"ThunderClose2\" }, 0.56, \"WorldSFX\", 130, 1900, 12, 2.5),\n\tThunderDistant = cue({ \"ThunderDistant1\", \"ThunderDistant2\" }, 0.34, \"WorldSFX\", 180, 2600, 14, 4, \"Distant\"),\n\tMeteorFlybySmall = cue({ \"MeteorWhooshSmall1\", \"MeteorWhooshSmall2\" }, 0.24, \"WorldSFX\", 70, 1300, 7, 0.8),\n\tMeteorFlybyLarge = cue({ \"MeteorWhooshLarge1\", \"MeteorWhooshLarge2\" }, 0.4, \"WorldSFX\", 160, 2200, 12, 3, \"Distant\"),\n\tMeteorImpactSmall = cue({ \"MeteorImpactSmall1\", \"MeteorImpactSmall2\" }, 0.36, \"ImpactSFX\", 95, 1400, 9, 0.8, \"Distant\"),\n\tMeteorImpactLarge = cue({ \"MeteorImpactLarge1\", \"MeteorImpactLarge2\" }, 0.62, \"ImpactSFX\", 230, 2900, 14, 3, \"Cosmic\"),\n\tRockDebris = cue({ \"RockDebris\" }, 0.14, \"ImpactSFX\", 20, 300, 4, 1),\n\tFireBurst = cue({ \"FireBurst\" }, 0.2, \"ImpactSFX\", 45, 650, 5, 2),\n\tFireCrackle = cue({ \"FireCrackle\" }, 0.1, \"ImpactSFX\", 20, 230, 6, 2),\n\tWindGust = cue({ \"WindGust1\", \"WindGust2\" }, 0.17, \"WeatherLoops\", 70, 900, 6, 4),\n\tSpiritPass = cue({ \"SpiritSweep\", \"SpiritChime\" }, 0.15, \"MagicalSFX\", 22, 250, 5, 3, \"Dream\"),\n\tSpiritWhisper = cue({ \"SpiritWhisper1\", \"SpiritWhisper2\" }, 0.055, \"MagicalSFX\", 16, 190, 5, 15),\n\tMagicBurst = cue({ \"CrystalChime1\", \"CrystalChime2\" }, 0.11, \"MagicalSFX\", 25, 420, 6, 3, \"Bright\"),\n\tMagicZap = cue({ \"MagicZap1\", \"MagicZap2\" }, 0.16, \"MagicalSFX\", 50, 850, 6, 2),\n\tEnergyStrike = cue({ \"CosmicEnergy1\", \"CosmicEnergy2\" }, 0.2, \"CelestialSFX\", 130, 2100, 9, 3, \"Cosmic\"),\n\tStarBurst = cue({ \"GoldenChime1\", \"GoldenChime2\" }, 0.13, \"MagicalSFX\", 30, 480, 6, 3, \"Bright\"),\n\tWaterSplash = cue({ \"RainSplash1\", \"RainSplash2\" }, 0.07, \"WorldSFX\", 14, 150, 3, 2),\n\tBird = cue({ \"Bird1\", \"Bird2\" }, 0.085, \"Ambience\", nil, nil, 6, 15),\n\tRainDrip = cue({ \"RainDrip1\" }, 0.055, \"Ambience\", nil, nil, 5, 12),\n\tForestDistant = cue({ \"DistantForestCue\" }, 0.07, \"Ambience\", nil, nil, 8, 18, \"Distant\"),\n\tAirySweep = cue({ \"AirySweep\" }, 0.09, \"CelestialSFX\", nil, nil, 8, 15, \"Dream\"),\n\tBloodPulse = cue({ \"BloodMoonPulse\" }, 0.12, \"CelestialSFX\", nil, nil, 8, 18, \"Ominous\"),\n\tDarkMagic = cue({ \"DarkMagic\", \"NightHowl\" }, 0.085, \"Ambience\", nil, nil, 9, 24, \"Distant\"),\n\tReverseSweep = cue({ \"ReverseSweep\" }, 0.11, \"Ambience\", nil, nil, 8, 14, \"Warped\"),\n\tNightmarePulse = cue({ \"NightmarePulse\", \"NightmareStinger\" }, 0.1, \"Ambience\", nil, nil, 8, 18, \"Ominous\"),\n\tCosmicTone = cue({ \"CosmicTone\" }, 0.12, \"CelestialSFX\", nil, nil, 10, 22, \"Cosmic\"),\n\tBloodMoonStart = cue({ \"BloodMoonStart\" }, 0.2, \"TransitionSFX\", nil, nil, 6, 0, \"Ominous\"),\n\tRainbowStart = cue({ \"RainbowStart\" }, 0.17, \"TransitionSFX\", nil, nil, 5, 0, \"Bright\"),\n\tVoidStart = cue({ \"VoidStart\" }, 0.19, \"TransitionSFX\", nil, nil, 7, 0, \"Cosmic\"),\n\tGoldenStart = cue({ \"GoldenStart\" }, 0.17, \"TransitionSFX\", nil, nil, 5, 0, \"Bright\"),\n\tAdminStart = cue({ \"AdminRealityBreak\" }, 0.22, \"TransitionSFX\", nil, nil, 6, 0),\n\tEnd = cue({ \"EventEnd\" }, 0.085, \"TransitionSFX\", nil, nil, 2, 0, \"Soft\"),\n}\nDefinitions.Cues.FireCrackle.Repeat = true -- Bounded six-second after-impact texture.\nDefinitions.Cues.MeteorImpactSmall.Followups = { \"RockDebris\", \"FireCrackle\" }\nDefinitions.Cues.MeteorImpactLarge.Followups = { \"RockDebris\", \"FireBurst\", \"FireCrackle\" }\n\n-- World cues are triggered by actual VFX, never by a disconnected sound timer.\n-- AmbientCues are deliberately sparse non-local texture, not fake impacts.\nDefinitions.Events = {\n\tSunnySkies = { Layers = { layer(\"Daytime\", \"DayAmbience\", 0.095, nil, \"Soft\"), layer(\"Foliage\", \"LeafRustle\", 0.055) }, AmbientCues = { \"Bird\" }, AmbientInterval = { 18, 34 } },\n\tRainyDay = { Layers = { layer(\"ModerateRain\", \"ExistingRain\", 0.32, \"WeatherLoops\", \"Soft\"), layer(\"DistantRain\", \"RainDistant\", 0.09, \"WeatherLoops\", \"Distant\"), layer(\"Breeze\", \"ExistingWind\", 0.065, nil, \"Soft\") }, AmbientCues = { \"RainDrip\" }, AmbientInterval = { 14, 25 } },\n\tThunderstorm = { Layers = { layer(\"HeavyRain\", \"ExistingRain\", 0.43, \"WeatherLoops\"), layer(\"StormWind\", \"ExistingWind\", 0.19, \"WeatherLoops\", \"Distant\"), layer(\"RainImpacts\", \"RainDistant\", 0.12, \"WeatherLoops\") } },\n\tSnowfall = { Layers = { layer(\"WinterWind\", \"WinterWind\", 0.13, \"WeatherLoops\", \"Cold\"), layer(\"QuietSnow\", \"WinterAmbience\", 0.075, nil, \"Soft\") } },\n\tFoggy = { Layers = { layer(\"FogDrone\", \"FogDrone\", 0.10, nil, \"Distant\"), layer(\"LowWind\", \"ExistingWind\", 0.055, nil, \"Soft\") }, AmbientCues = { \"ForestDistant\" }, AmbientInterval = { 24, 43 } },\n\tWindy = { Layers = { layer(\"Wind\", \"ExistingWind\", 0.28, \"WeatherLoops\"), layer(\"Rustle\", \"LeafRustle\", 0.13, \"WeatherLoops\") } },\n\tHeatwave = { Layers = { layer(\"DryWind\", \"DryWind\", 0.11, nil, \"Dry\"), layer(\"HeatInsects\", \"HeatInsects\", 0.085) } },\n\tAurora = { Layers = { layer(\"AuroraPad\", \"AuroraPad\", 0.15, nil, \"Dream\"), layer(\"Shimmer\", \"MagicShimmer\", 0.06, \"MagicalSFX\", \"Bright\"), layer(\"NightAir\", \"ExistingWind\", 0.055, nil, \"Soft\") }, AmbientCues = { \"AirySweep\" }, AmbientInterval = { 21, 36 }, StartCue = \"AirySweep\" },\n\tBloodMoon = { Layers = { layer(\"MoonDrone\", \"BloodMoonAmbience\", 0.22, nil, \"Ominous\"), layer(\"EerieAir\", \"ExistingWind\", 0.065, nil, \"Distant\") }, AmbientCues = { \"BloodPulse\", \"DarkMagic\" }, AmbientInterval = { 22, 38 }, StartCue = \"BloodMoonStart\" },\n\tMeteorShower = { Layers = { layer(\"SkyRumble\", \"MeteorSkyRumble\", 0.12, nil, \"Distant\"), layer(\"NightAir\", \"ExistingWind\", 0.085, nil, \"Cold\") } },\n\tSpiritNight = { Layers = { layer(\"SpiritBed\", \"SpiritAmbience\", 0.17, nil, \"Dream\"), layer(\"Air\", \"ExistingWind\", 0.055, nil, \"Soft\"), layer(\"Shimmer\", \"MagicShimmer\", 0.055, \"MagicalSFX\") } },\n\tRainbow = { Layers = { layer(\"RainbowBed\", \"RainbowAmbience\", 0.14, nil, \"Bright\"), layer(\"Glitter\", \"MagicShimmer\", 0.045, \"MagicalSFX\", \"Bright\"), layer(\"Breeze\", \"ExistingWind\", 0.06, nil, \"Soft\") }, StartCue = \"RainbowStart\" },\n\t-- Match the VFX's four five-second stages: rain/lightning, fire, snow/magic, energy.\n\tChaos = { Layers = { layer(\"Warp\", \"ChaosWarp\", 0.13, nil, \"Warped\"), layer(\"RainCycle\", \"ExistingRain\", 0.12, \"WeatherLoops\", \"Soft\", { 20, 5, 2, true }), layer(\"WindCycle\", \"ExistingWind\", 0.12, \"WeatherLoops\", \"Cold\", { 20, 5, 12 }) }, AmbientCues = { \"ReverseSweep\" }, AmbientInterval = { 18, 29 } },\n\tInverted = { Layers = { layer(\"InvertedBed\", \"InvertedAmbience\", 0.15, nil, \"Warped\"), layer(\"WrongAir\", \"ExistingWind\", 0.07, nil, \"Cold\") }, AmbientCues = { \"ReverseSweep\" }, AmbientInterval = { 17, 29 }, StartCue = \"ReverseSweep\" },\n\tNightmare = { Layers = { layer(\"NightmareBed\", \"NightmareDrone\", 0.20, nil, \"Ominous\"), layer(\"ColdAir\", \"ExistingWind\", 0.09, nil, \"Distant\") }, AmbientCues = { \"NightmarePulse\" }, AmbientInterval = { 23, 39 } },\n\tVoid = { Layers = { layer(\"VoidBed\", \"VoidAmbience\", 0.19, nil, \"Cosmic\"), layer(\"CosmicRumble\", \"CosmicRumble\", 0.11, \"CelestialSFX\", \"Cosmic\"), layer(\"SpaceDust\", \"MagicShimmer\", 0.04, \"CelestialSFX\", \"Dream\") }, AmbientCues = { \"CosmicTone\" }, AmbientInterval = { 25, 42 }, StartCue = \"VoidStart\" },\n\tGolden = { Layers = { layer(\"GoldenBed\", \"GoldenAmbience\", 0.13, nil, \"Bright\"), layer(\"GoldShimmer\", \"MagicShimmer\", 0.065, \"MagicalSFX\", \"Bright\"), layer(\"WarmAir\", \"ExistingWind\", 0.055, nil, \"Soft\") }, StartCue = \"GoldenStart\" },\n\t-- Same sequence at 3.7 seconds per stage; cosmic rumble accompanies energy stage 3.\n\tAdminAbuse = { Layers = { layer(\"RealityWarp\", \"ChaosWarp\", 0.14, nil, \"Warped\"), layer(\"RainCycle\", \"ExistingRain\", 0.18, \"WeatherLoops\", \"Natural\", { 14.8, 3.7, 2, true }), layer(\"CosmicCycle\", \"CosmicRumble\", 0.13, \"CelestialSFX\", \"Cosmic\", { 14.8, 3.7, 13.1 }) }, AmbientCues = { \"ReverseSweep\", \"CosmicTone\" }, AmbientInterval = { 15, 25 }, StartCue = \"AdminStart\" },\n}\n\nDefinitions.Categories = { \"Ambience\", \"WeatherLoops\", \"WorldSFX\", \"ImpactSFX\", \"MagicalSFX\", \"CelestialSFX\", \"TransitionSFX\" }\n\nfunction Definitions.GetMissingAssets()\n\tlocal missing = {}\n\tfor name, asset in pairs(Definitions.Assets) do\n\t\tif asset.SoundId == \"\" then table.insert(missing, name) end\n\tend\n\ttable.sort(missing)\n\treturn missing\nend\n\nreturn Definitions\n"}, {"path": ["ReplicatedStorage", "Shared", "WeatherAudioController"], "class": "ModuleScript", "source": "-- Client-local weather mixer. Server weather state remains entirely unchanged.\n-- Positional cues are called by the VFX that actually produced them.\nlocal RunService = game:GetService(\"RunService\")\nlocal SoundService = game:GetService(\"SoundService\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Definitions = require(script.Parent:WaitForChild(\"WeatherSoundDefinitions\"))\n\nlocal Audio = {}\nlocal Session = {}\nSession.__index = Session\nlocal activeSession\nlocal missingReported = {}\nlocal unavailableAssets = {}\n\nlocal function cycleEnabled(elapsed, cycle)\n\t-- {period, active duration, offset, active during the initial lead-in}.\n\t-- WeatherEnvironmentEffects starts its four-stage sequence after two seconds.\n\tif elapsed < cycle[3] then return cycle[4] == true end\n\treturn (elapsed - cycle[3]) % cycle[1] < cycle[2]\nend\n\nlocal function folder(name, parent)\n\tlocal object = Instance.new(\"Folder\")\n\tobject.Name = name\n\tobject.Parent = parent\n\treturn object\nend\n\nlocal function assetFor(names, random)\n\tlocal candidates = {}\n\tlocal used = {}\n\tfor _, name in ipairs(names or {}) do\n\t\tlocal visited = {}\n\t\tlocal resolved = name\n\t\twhile resolved and not visited[resolved] do\n\t\t\tvisited[resolved] = true\n\t\t\tlocal asset = Definitions.Assets[resolved]\n\t\t\tif not asset then break end\n\t\t\tif asset.SoundId ~= \"\" then\n\t\t\t\tif not unavailableAssets[asset.SoundId] and not used[asset.SoundId] then\n\t\t\t\t\tused[asset.SoundId] = true\n\t\t\t\t\ttable.insert(candidates, { Name = resolved, Id = asset.SoundId, Requested = name })\n\t\t\t\tend\n\t\t\t\tbreak\n\t\t\tend\n\t\t\tresolved = asset.Fallback\n\t\tend\n\tend\n\tif #candidates == 0 then return nil end\n\treturn candidates[random:NextInteger(1, #candidates)]\nend\n\nlocal function positionOf(target)\n\tif typeof(target) == \"Vector3\" then return target end\n\tif typeof(target) == \"Instance\" and target:IsA(\"BasePart\") and target.Parent then return target.Position end\n\tif typeof(target) == \"Instance\" and target:IsA(\"Attachment\") and target.Parent then return target.WorldPosition end\n\treturn nil\nend\n\nlocal function toneFor(sound, name)\n\tlocal recipe = Definitions.Tones[name]\n\tif not recipe then return end\n\tlocal equalizer = Instance.new(\"EqualizerSoundEffect\")\n\tequalizer.Name = \"WeatherTone\"\n\tequalizer.LowGain = recipe.Low\n\tequalizer.MidGain = recipe.Mid\n\tequalizer.HighGain = recipe.High\n\tequalizer.Parent = sound\nend\n\nfunction Session:_fade(voice, volume, seconds)\n\tif voice.Tween then voice.Tween:Cancel(); voice.Tween = nil end\n\tif not voice.Sound.Parent then return end\n\tif seconds <= 0 then voice.Sound.Volume = volume; return end\n\tvoice.Tween = TweenService:Create(voice.Sound, TweenInfo.new(seconds, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), { Volume = volume })\n\tvoice.Tween:Play()\nend\n\nfunction Session:_release(voice)\n\tif voice.Released then return end\n\tvoice.Released = true\n\tif voice.Connection then voice.Connection:Disconnect(); voice.Connection = nil end\n\tif voice.Tween then voice.Tween:Cancel(); voice.Tween = nil end\n\tself.Voices[voice] = nil\n\tif voice.IsLayer then\n\t\tself.LoopCount = math.max(0, self.LoopCount - 1)\n\t\tself.LoopIds[voice.AssetId] = nil\n\telse\n\t\tself.OneShotCount = math.max(0, self.OneShotCount - 1)\n\tend\n\tvoice.Sound:Stop()\n\tvoice.Sound:Destroy()\n\tif voice.Anchor then voice.Anchor:Destroy() end\nend\n\nfunction Session:_voice(asset, recipe, target, options, isLayer)\n\tif self.Dead or (self.Stopping and not options.ExitCue) then return nil end\n\tif self.LoopCount + self.OneShotCount >= Definitions.Mix.MaxVoices then return nil end\n\tif isLayer then\n\t\tif self.LoopCount >= Definitions.Mix.MaxLoops or self.LoopIds[asset.Id] then return nil end\n\telseif self.OneShotCount >= Definitions.Mix.MaxOneShots then\n\t\treturn nil\n\tend\n\tlocal category = recipe.Category or \"Ambience\"\n\tlocal anchor\n\tlocal parent = self.Categories[category]\n\tlocal position = positionOf(target)\n\t-- Never turn an invalid positional sound into a centered global sound.\n\tif recipe.MinDistance and not position then return nil end\n\tif position then\n\t\tif typeof(target) == \"Instance\" then\n\t\t\tparent = target\n\t\telse\n\t\t\tanchor = Instance.new(\"Part\")\n\t\t\tanchor.Name = options.Name or \"WeatherSoundAnchor\"\n\t\t\tanchor.Anchored = true\n\t\t\tanchor.CanCollide = false\n\t\t\tanchor.CanTouch = false\n\t\t\tanchor.CanQuery = false\n\t\t\tanchor.CastShadow = false\n\t\t\tanchor.Transparency = 1\n\t\t\tanchor.Size = Vector3.new(0.1, 0.1, 0.1)\n\t\t\tanchor.Position = position\n\t\t\tanchor:SetAttribute(\"AudioCategory\", category)\n\t\t\tanchor.Parent = self.WorldCategories[category]\n\t\t\tparent = anchor\n\t\tend\n\tend\n\tlocal sound = Instance.new(\"Sound\")\n\tsound.Name = options.Name or recipe.Name or asset.Requested\n\tsound.SoundId = asset.Id\n\tsound.SoundGroup = self.MixGroup\n\tsound.Volume = 0\n\tsound.Looped = isLayer or recipe.Repeat == true\n\tsound.PlaybackSpeed = isLayer and 1 or self.Random:NextNumber(0.94, 1.06)\n\tsound.RollOffMode = Enum.RollOffMode.InverseTapered\n\tsound.RollOffMinDistance = recipe.MinDistance or 20\n\tsound.RollOffMaxDistance = recipe.MaxDistance or 450\n\tsound:SetAttribute(\"WeatherEventId\", self.EventId)\n\tsound:SetAttribute(\"AudioCategory\", category)\n\tsound:SetAttribute(\"RequestedAsset\", asset.Requested)\n\tsound:SetAttribute(\"ResolvedAsset\", asset.Name)\n\ttoneFor(sound, recipe.Tone)\n\tsound.Parent = parent\n\tlocal now = os.clock()\n\tlocal volume = math.clamp((recipe.Volume or 0.1) * (options.VolumeScale or 1), 0, 0.7)\n\tlocal voice = {\n\t\tSound = sound, Anchor = anchor, IsLayer = isLayer, AssetId = asset.Id,\n\t\tTargetVolume = volume, Birth = now, Recipe = recipe, CheckedLoad = false,\n\t\tExpires = not isLayer and now + math.clamp(options.Duration or recipe.Duration or 12, 0.2, 20) or nil,\n\t}\n\tself.Voices[voice] = true\n\tif isLayer then\n\t\tself.LoopCount += 1\n\t\tself.LoopIds[asset.Id] = true\n\telse\n\t\tself.OneShotCount += 1\n\tend\n\tvoice.Connection = sound.Ended:Connect(function() self:_release(voice) end)\n\tsound:Play()\n\tlocal initialVolume = volume\n\tif isLayer and recipe.Cycle then\n\t\tlocal cycle = recipe.Cycle\n\t\tlocal elapsed = math.max(0, workspace:GetServerTimeNow() - self.StartedAt)\n\t\t\tvoice.CycleOn = cycleEnabled(elapsed, cycle)\n\t\tinitialVolume = voice.CycleOn and volume or 0\n\tend\n\tself:_fade(voice, initialVolume, isLayer and Definitions.Mix.FadeIn or 0.06)\n\treturn sound\nend\n\nfunction Session:_play(cueName, target, options)\n\tlocal recipe = Definitions.Cues[cueName]\n\tif not recipe then return nil end\n\tlocal asset = assetFor(recipe.Assets, self.Random)\n\tif not asset then return nil end\n\toptions.Name = cueName\n\tlocal sound = self:_voice(asset, recipe, target, options, false)\n\tif sound and recipe.Followups then\n\t\tfor _, nextCue in ipairs(recipe.Followups) do\n\t\t\tself:PlayCue(nextCue, target, { Delay = 0.08, VolumeScale = options.VolumeScale or 1 })\n\t\tend\n\tend\n\treturn sound\nend\n\n-- Supported cue names are in WeatherSoundDefinitions.Cues. A Vector3 creates\n-- a fixed anchor; a BasePart/Attachment attaches the sound to that moving VFX.\n-- Options: VolumeScale (0..safe mix cap), Duration (<=20), Delay (seconds).\nfunction Session:PlayCue(cueName, target, options)\n\tif self.Dead or self.Stopping then return nil end\n\tlocal recipe = Definitions.Cues[cueName]\n\tif not recipe then return nil end\n\tif not assetFor(recipe.Assets, self.Random) then return nil end\n\toptions = table.clone(options or {})\n\tlocal now = os.clock()\n\tif now < (self.Cooldowns[cueName] or 0) then return nil end\n\tlocal position = positionOf(target)\n\tif recipe.MinDistance and not position then return nil end\n\tlocal delay = options.Delay or 0\n\tif options.Delay == nil and (cueName == \"ThunderStrike\" or cueName == \"ThunderDistant\") and position then\n\t\tlocal camera = workspace.CurrentCamera\n\t\t-- Camera is read only to approximate the listener's acoustic distance.\n\t\t-- No world audio or world visual object is positioned from this camera.\n\t\tif camera then delay = math.clamp((camera.CFrame.Position - position).Magnitude / 1100, 0.05, 2.5) end\n\tend\n\tif delay > 0 then\n\t\tif #self.Pending >= Definitions.Mix.MaxPendingCues then return nil end\n\t\tself.Cooldowns[cueName] = now + (recipe.Cooldown or 1)\n\t\ttable.insert(self.Pending, { At = now + math.min(delay, 5), Cue = cueName, Target = target, Options = options })\n\t\treturn nil\n\tend\n\tlocal sound = self:_play(cueName, target, options)\n\tif sound then self.Cooldowns[cueName] = now + (recipe.Cooldown or 1) end\n\treturn sound\nend\n\nfunction Session:_update()\n\tif self.Dead then return end\n\tlocal now = os.clock()\n\tif self.Stopping then\n\t\tif now >= self.StopAt then self:CleanupAudio() end\n\t\treturn\n\tend\n\tif not self.Runtime.Parent then self:CleanupAudio(); return end\n\tfor i = #self.Pending, 1, -1 do\n\t\tlocal pending = self.Pending[i]\n\t\tif now >= pending.At then\n\t\t\ttable.remove(self.Pending, i)\n\t\t\tself:_play(pending.Cue, pending.Target, pending.Options)\n\t\tend\n\tend\n\tlocal elapsed = math.max(0, workspace:GetServerTimeNow() - self.StartedAt)\n\tlocal release = {}\n\tfor voice in pairs(self.Voices) do\n\t\tif not voice.Sound.Parent or (voice.Expires and now >= voice.Expires) then\n\t\t\ttable.insert(release, voice)\n\t\telse\n\t\t\tif not voice.CheckedLoad and now - voice.Birth > 8 then\n\t\t\t\tvoice.CheckedLoad = true\n\t\t\t\tif not voice.Sound.IsLoaded then\n\t\t\t\t\tif not unavailableAssets[voice.AssetId] and RunService:IsStudio() then\n\t\t\t\t\t\twarn(\"[WeatherAudio] Unavailable audio skipped: \" .. voice.AssetId .. \". Assign an experience-permitted asset in WeatherSoundDefinitions.\")\n\t\t\t\t\tend\n\t\t\t\t\tunavailableAssets[voice.AssetId] = true\n\t\t\t\t\ttable.insert(release, voice)\n\t\t\t\tend\n\t\t\tend\n\t\t\tlocal cycle = voice.IsLayer and voice.Recipe.Cycle\n\t\t\tif cycle then\n\t\t\t\tlocal on = cycleEnabled(elapsed, cycle)\n\t\t\t\tif on ~= voice.CycleOn then\n\t\t\t\t\tvoice.CycleOn = on\n\t\t\t\t\tself:_fade(voice, on and voice.TargetVolume or 0, 1.8)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\tfor _, voice in ipairs(release) do self:_release(voice) end\n\tif now >= self.NextAmbient then\n\t\tlocal cues = self.Profile.AmbientCues\n\t\tif cues and #cues > 0 then self:PlayCue(cues[self.Random:NextInteger(1, #cues)]) end\n\t\tlocal interval = self.Profile.AmbientInterval or { 18, 32 }\n\t\tself.NextAmbient = now + self.Random:NextNumber(interval[1], interval[2])\n\tend\nend\n\nfunction Session:StopAudio(fadeSeconds)\n\tif self.Dead or self.Stopping then return end\n\tlocal fade = math.clamp(fadeSeconds or Definitions.Mix.FadeOut, 0, 3)\n\tself.Stopping = true\n\tself.Pending = {}\n\tself.StopAt = os.clock() + fade\n\tif fade <= 0 then self:CleanupAudio(); return end\n\tfor voice in pairs(self.Voices) do self:_fade(voice, 0, fade) end\n\t-- This optional exit cue is owned by this session and removed at the same\n\t-- deadline. Starting the next event immediately clears this whole session.\n\tself:_play(\"End\", nil, { ExitCue = true, Duration = fade, VolumeScale = 0.65 })\nend\n\nfunction Session:CleanupAudio()\n\tif self.Dead then return end\n\tself.Dead = true\n\tself.Stopping = true\n\tself.Pending = {}\n\tif self.Connection then self.Connection:Disconnect(); self.Connection = nil end\n\tlocal voices = {}\n\tfor voice in pairs(self.Voices) do table.insert(voices, voice) end\n\tfor _, voice in ipairs(voices) do self:_release(voice) end\n\tself.WorldFolder:Destroy()\n\tself.Root:Destroy()\n\tif activeSession == self then activeSession = nil end\nend\n\nfunction Session:GetStats()\n\treturn { Loops = self.LoopCount, OneShots = self.OneShotCount, Pending = #self.Pending,\n\t\tDead = self.Dead, Stopping = self.Stopping == true, EventId = self.EventId }\nend\n\nfunction Audio.Start(eventId, startedAt, runtime)\n\tassert(RunService:IsClient(), \"WeatherAudioController is client presentation only\")\n\tassert(typeof(runtime) == \"Instance\", \"Weather audio requires the current event runtime container\")\n\tif activeSession then activeSession:CleanupAudio() end\n\tlocal stale = SoundService:FindFirstChild(\"AK_WeatherAudio\")\n\tif stale then stale:Destroy() end\n\tlocal self = setmetatable({}, Session)\n\tself.EventId = eventId\n\tself.StartedAt = type(startedAt) == \"number\" and startedAt > 0 and startedAt or workspace:GetServerTimeNow()\n\tself.Profile = Definitions.Events[eventId] or { Layers = {} }\n\tself.Runtime = runtime\n\tself.Random = Random.new()\n\tself.Root = folder(\"AK_WeatherAudio\", SoundService)\n\tself.Root:SetAttribute(\"WeatherEventId\", eventId)\n\tself.Root:SetAttribute(\"StartedAt\", self.StartedAt)\n\tself.EventFolder = folder(eventId, self.Root)\n\tself.WorldFolder = folder(\"EventAudio\", runtime)\n\tself.MixGroup = Instance.new(\"SoundGroup\")\n\tself.MixGroup.Name = \"WeatherMix\"\n\tself.MixGroup.Volume = Definitions.Mix.MasterVolume\n\tself.MixGroup.Parent = self.Root\n\tself.Categories = {}\n\tself.WorldCategories = {}\n\tfor _, category in ipairs(Definitions.Categories) do\n\t\tself.Categories[category] = folder(category, self.EventFolder)\n\t\tself.WorldCategories[category] = folder(category, self.WorldFolder)\n\tend\n\tself.Voices = {}\n\tself.LoopIds = {}\n\tself.Pending = {}\n\tself.Cooldowns = {}\n\tself.LoopCount = 0\n\tself.OneShotCount = 0\n\tself.NextAmbient = os.clock() + self.Random:NextNumber(12, 20)\n\tactiveSession = self\n\tfor _, recipe in ipairs(self.Profile.Layers) do\n\t\tlocal asset = assetFor(recipe.Assets, self.Random)\n\t\tif asset then self:_voice(asset, recipe, nil, {}, true) end\n\tend\n\tif self.Profile.StartCue then self:PlayCue(self.Profile.StartCue) end\n\tif RunService:IsStudio() and not missingReported[eventId] then\n\t\tmissingReported[eventId] = true\n\t\tlocal missing = Definitions.GetMissingAssets()\n\t\tif #missing > 0 then\n\t\t\tprint(\"[WeatherAudio] \" .. eventId .. \": configured mix active; \" .. #missing .. \" upload slots remain unassigned. See WeatherSoundDefinitions / AUDIO-MANIFEST.md.\")\n\t\tend\n\tend\n\tlocal accumulator = 0\n\tself.Connection = RunService.Heartbeat:Connect(function(dt)\n\t\taccumulator += dt\n\t\tif accumulator < Definitions.Mix.UpdateInterval then return end\n\t\taccumulator = 0\n\t\tself:_update()\n\tend)\n\treturn self\nend\n\nAudio.StartAudio = Audio.Start\nAudio.Definitions = Definitions\nreturn Audio\n"}, {"path": ["ReplicatedStorage", "Shared", "WeatherCelestialEffects"], "class": "ModuleScript", "source": "-- Distant, cosmetic world objects. Anchors never depend on a camera or player.\n-- Shared server time drives movement so every client sees the same sky region.\nlocal RunService = game:GetService(\"RunService\")\nlocal Lighting = game:GetService(\"Lighting\")\n\nlocal Celestial = {}\nlocal WHITE = Color3.new(1, 1, 1)\nlocal WORLD_CENTER = Vector3.new(-338, 8, 248)\nlocal ANIMATION_STEP = 1 / 15\nlocal POSITIONS = {\n\tBloodMoon = Vector3.new(-6338, 8008, -23752),\n\tRainbow = Vector3.new(-500, 60, -2200),\n\tAurora = Vector3.new(-500, 850, -1700),\n\tVoidPlanet = Vector3.new(-3600, 1700, -7000),\n\tVoidMoon = Vector3.new(1300, 2600, -9200),\n\tAdminPlanet = Vector3.new(-1850, 2000, -4700),\n}\n\nlocal function part(parent, name, position, size, tint, transparency)\n\tlocal object = Instance.new(\"Part\")\n\tobject.Name = name\n\tobject.Anchored = true\n\tobject.CanCollide = false\n\tobject.CanTouch = false\n\tobject.CanQuery = false\n\tobject.CastShadow = false\n\tobject.Material = Enum.Material.Neon\n\tobject.Color = tint or WHITE\n\tobject.Transparency = transparency or 0\n\tobject.Size = size or Vector3.one\n\tobject.Position = position\n\tobject.Parent = parent\n\treturn object\nend\n\nlocal function anchor(parent, name, position)\n\tlocal object = part(parent, name, position, Vector3.one, WHITE, 1)\n\tobject:SetAttribute(\"FixedWorldPosition\", position)\n\treturn object\nend\n\nlocal function attachment(parent, name, position, tangent)\n\tlocal object = Instance.new(\"Attachment\")\n\tobject.Name = name\n\tobject.Position = position\n\tobject.Axis = tangent or Vector3.xAxis\n\tobject.Parent = parent\n\treturn object\nend\n\nlocal function beam(parent, name, from, to, tint, width, curve)\n\tlocal object = Instance.new(\"Beam\")\n\tobject.Name = name\n\tobject.Attachment0 = from\n\tobject.Attachment1 = to\n\tobject.Color = ColorSequence.new(tint)\n\tobject.Width0 = width\n\tobject.Width1 = width\n\tobject.CurveSize0 = curve or 0\n\tobject.CurveSize1 = curve or 0\n\tobject.Segments = 24\n\t-- Facing the viewer affects ribbon thickness, never its anchored world path.\n\tobject.FaceCamera = true\n\tobject.LightEmission = 1\n\tobject.LightInfluence = 0\n\tobject.Transparency = NumberSequence.new(0.22)\n\tobject.Parent = parent\n\treturn object\nend\n\nlocal function circle(parent, name, size, position, tint, transparency)\n\tlocal frame = Instance.new(\"Frame\")\n\tframe.Name = name\n\tframe.AnchorPoint = Vector2.new(0.5, 0.5)\n\tframe.Size = UDim2.fromScale(size, size)\n\tframe.Position = position\n\tframe.BackgroundColor3 = tint\n\tframe.BackgroundTransparency = transparency or 0\n\tframe.BorderSizePixel = 0\n\tframe.Parent = parent\n\tlocal corner = Instance.new(\"UICorner\")\n\tcorner.CornerRadius = UDim.new(1, 0)\n\tcorner.Parent = frame\n\treturn frame\nend\n\nlocal function softEmitter(parent, name, tint, size, rate)\n\tlocal emitter = Instance.new(\"ParticleEmitter\")\n\temitter.Name = name\n\temitter.Texture = \"rbxasset://textures/particles/smoke_main.dds\"\n\temitter.Shape = Enum.ParticleEmitterShape.Box\n\temitter.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume\n\temitter.EmissionDirection = Enum.NormalId.Top\n\temitter.Rate = rate\n\temitter.Lifetime = NumberRange.new(9, 13)\n\temitter.Speed = NumberRange.new(12, 24)\n\temitter.SpreadAngle = Vector2.new(160, 160)\n\temitter.Rotation = NumberRange.new(0, 360)\n\temitter.RotSpeed = NumberRange.new(-3, 3)\n\temitter.Color = ColorSequence.new(tint)\n\temitter.LightEmission = 0.65\n\temitter.LightInfluence = 0\n\temitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, size * 0.7), NumberSequenceKeypoint.new(1, size) })\n\temitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.25, 0.86), NumberSequenceKeypoint.new(0.65, 0.9), NumberSequenceKeypoint.new(1, 1) })\n\temitter.LockedToPart = false\n\temitter.Parent = parent\n\treturn emitter\nend\n\nlocal function addStars(parent, quality, tint, seed)\n\tlocal stars = {}\n\tlocal rng = Random.new(seed)\n\tlocal count = math.floor(8 + 24 * quality) -- 32 High / 16 Low; fewer for Moon/Spirit.\n\tfor index = 1, count do\n\t\tlocal azimuth = rng:NextNumber(0, math.pi * 2)\n\t\tlocal elevation = rng:NextNumber(0.23, 1.15)\n\t\tlocal distance = rng:NextNumber(4800, 7200)\n\t\tlocal position = WORLD_CENTER + Vector3.new(math.cos(azimuth) * math.cos(elevation), math.sin(elevation), math.sin(azimuth) * math.cos(elevation)) * distance\n\t\tlocal star = anchor(parent, \"WorldStar\", position)\n\t\tlocal billboard = Instance.new(\"BillboardGui\")\n\t\tbillboard.Name = \"WorldStarGlint\"\n\t\tbillboard.Adornee = star\n\t\tlocal size = rng:NextNumber(24, 38)\n\t\tbillboard.Size = UDim2.fromScale(size, size)\n\t\tbillboard.AlwaysOnTop = false\n\t\tbillboard.LightInfluence = 0\n\t\tbillboard.Brightness = 1.5\n\t\tbillboard.MaxDistance = 0\n\t\tbillboard.Parent = star\n\t\tlocal color = tint:Lerp(WHITE, rng:NextNumber(0.1, 0.8))\n\t\tlocal halo = circle(billboard, \"StarHalo\", 1, UDim2.fromScale(0.5, 0.5), color, 0.82)\n\t\tlocal glint = circle(billboard, \"StarCore\", 0.65, UDim2.fromScale(0.5, 0.5), color, 0.1)\n\t\tstars[index] = { glint = glint, halo = halo, phase = rng:NextNumber(0, 6.28) }\n\tend\n\treturn stars\nend\n\nlocal function addRainbow(parent)\n\tlocal object = anchor(parent, \"RainbowAnchor\", POSITIONS.Rainbow)\n\tlocal colors = { Color3.fromRGB(255, 90, 103), Color3.fromRGB(255, 177, 80), Color3.fromRGB(255, 237, 104), Color3.fromRGB(114, 227, 147), Color3.fromRGB(110, 188, 255), Color3.fromRGB(114, 123, 243), Color3.fromRGB(186, 132, 255) }\n\tfor index, tint in ipairs(colors) do\n\t\tlocal radius = 1204 - (index - 1) * 24.64\n\t\tlocal curve = radius * 0.5522847498\n\t\tlocal left = attachment(object, \"Left\" .. index, Vector3.new(-radius, 0, 0), Vector3.yAxis)\n\t\tlocal top = attachment(object, \"Top\" .. index, Vector3.new(0, radius, 0), Vector3.xAxis)\n\t\tlocal right = attachment(object, \"Right\" .. index, Vector3.new(radius, 0, 0), -Vector3.yAxis)\n\t\tfor _, arc in ipairs({ beam(object, \"RainbowArc\", left, top, tint, 24.08, curve), beam(object, \"RainbowArc\", top, right, tint, 24.08, curve) }) do\n\t\t\tarc.Segments = 64\n\t\t\tarc.LightEmission = 0\n\t\t\tarc.Transparency = NumberSequence.new(0.15)\n\t\tend\n\tend\n\treturn object\nend\n\nlocal function addBloodMoon(parent)\n\tlocal object = anchor(parent, \"BloodMoonAnchor\", POSITIONS.BloodMoon)\n\tlocal billboard = Instance.new(\"BillboardGui\")\n\tbillboard.Name = \"BloodMoonDisc\"\n\tbillboard.Adornee = object\n\t-- Scale components are studs, not pixels. The disc naturally leaves the view\n\t-- when the player turns away and remains occluded by intervening geometry.\n\tbillboard.Size = UDim2.fromScale(5600, 5600)\n\tbillboard.AlwaysOnTop = false\n\tbillboard.LightInfluence = 0\n\tbillboard.Brightness = 1.5\n\tbillboard.MaxDistance = 0\n\tbillboard.Parent = object\n\tlocal halos = {}\n\tfor index = 1, 5 do\n\t\tlocal halo = circle(billboard, \"RedCorona\" .. index, 1 - (index - 1) * 0.034, UDim2.fromScale(0.5, 0.5), Color3.fromRGB(249, 44, 40), 0.96 - index * 0.009)\n\t\thalos[index] = halo\n\tend\n\tlocal face = circle(billboard, \"MoonFace\", 0.79, UDim2.fromScale(0.5, 0.5), Color3.fromRGB(255, 133, 102))\n\tlocal gradient = Instance.new(\"UIGradient\")\n\tgradient.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 213, 153)), ColorSequenceKeypoint.new(0.4, Color3.fromRGB(239, 90, 70)), ColorSequenceKeypoint.new(1, Color3.fromRGB(93, 16, 35)) })\n\tgradient.Rotation = 32\n\tgradient.Parent = face\n\tfor index, crater in ipairs({ {0.3, 0.31, 0.2}, {0.66, 0.28, 0.13}, {0.59, 0.64, 0.23}, {0.28, 0.65, 0.11}, {0.77, 0.49, 0.09}, {0.46, 0.43, 0.12}, {0.39, 0.79, 0.065}, {0.73, 0.72, 0.08}, {0.47, 0.19, 0.065} }) do\n\t\tlocal rim = circle(face, \"CraterRim\" .. index, crater[3], UDim2.fromScale(crater[1], crater[2]), Color3.fromRGB(255, 173, 119), 0.7)\n\t\tcircle(rim, \"CraterBasin\", 0.84, UDim2.fromScale(0.54, 0.49), Color3.fromRGB(89, 22, 34), 0.42)\n\tend\n\treturn halos\nend\n\nlocal function addAurora(parent, quality)\n\tlocal object = anchor(parent, \"AuroraAnchor\", POSITIONS.Aurora)\n\tlocal ribbons = {}\n\tlocal colors = { Color3.fromRGB(73, 255, 179), Color3.fromRGB(73, 225, 255), Color3.fromRGB(128, 159, 255), Color3.fromRGB(201, 118, 255), Color3.fromRGB(116, 255, 204) }\n\tlocal count = quality < 0.55 and 3 or 5\n\tfor row = 1, count do\n\t\t-- A continuous cubic strip has no interior endpoint seam. A faint wider\n\t\t-- second strip softens its edge without transparent geometry stacks.\n\t\tlocal from = attachment(object, \"AuroraStart\", Vector3.new(-1500, row * 75, row * 95), Vector3.xAxis)\n\t\tlocal to = attachment(object, \"AuroraEnd\", Vector3.new(1500, row * 75, row * 95), Vector3.xAxis)\n\t\tlocal bands = {}\n\t\tfor layer = 1, 2 do\n\t\t\tlocal ribbon = beam(object, layer == 1 and \"AuroraRibbon\" or \"AuroraGlow\", from, to, colors[row], layer == 1 and 125 or 235, 1100)\n\t\t\tribbon.Segments = 64\n\t\t\tribbon.Color = ColorSequence.new(colors[row], colors[row % #colors + 1])\n\t\t\tribbon.Transparency = NumberSequence.new({\n\t\t\t\tNumberSequenceKeypoint.new(0, 1),\n\t\t\t\tNumberSequenceKeypoint.new(0.2, layer == 1 and 0.57 or 0.95),\n\t\t\t\tNumberSequenceKeypoint.new(0.5, layer == 1 and 0.35 or 0.88),\n\t\t\t\tNumberSequenceKeypoint.new(0.8, layer == 1 and 0.57 or 0.95),\n\t\t\t\tNumberSequenceKeypoint.new(1, 1),\n\t\t\t})\n\t\t\tbands[layer] = ribbon\n\t\tend\n\t\tribbons[row] = { points = {from, to}, beams = bands }\n\tend\n\treturn ribbons\nend\n\nlocal function planetBillboard(object, name, diameter)\n\tlocal billboard = Instance.new(\"BillboardGui\")\n\tbillboard.Name = name\n\tbillboard.Adornee = object\n\tbillboard.Size = UDim2.fromScale(diameter, diameter)\n\tbillboard.AlwaysOnTop = false\n\tbillboard.LightInfluence = 0\n\tbillboard.Brightness = 1.25\n\tbillboard.MaxDistance = 0\n\tbillboard.ZIndexBehavior = Enum.ZIndexBehavior.Global\n\tbillboard.Parent = object\n\treturn billboard\nend\n\nlocal function addPlanet(parent, name, position, diameter, tint, secondary, ringed)\n\tlocal object = anchor(parent, name .. \"Anchor\", position)\n\t-- Far physical spheres disappear at some Studio rendering settings. The\n\t-- tested moon-style billboard is world sized and anchored at the SAME\n\t-- distant coordinates, with normal building/terrain occlusion.\n\tlocal billboard = planetBillboard(object, name .. \"Disc\", diameter * 1.85)\n\tlocal glow = circle(billboard, \"PlanetAtmosphere\", 0.6, UDim2.fromScale(0.5, 0.5), secondary, 0.9)\n\tglow.ZIndex = 1\n\tlocal body = circle(billboard, name .. \"Body\", 1 / 1.85, UDim2.fromScale(0.5, 0.5), WHITE)\n\tbody.ZIndex = 2\n\tlocal gradient = Instance.new(\"UIGradient\")\n\tgradient.Color = ColorSequence.new({\n\t\tColorSequenceKeypoint.new(0, secondary:Lerp(WHITE, 0.42)),\n\t\tColorSequenceKeypoint.new(0.35, secondary),\n\t\tColorSequenceKeypoint.new(0.67, tint),\n\t\tColorSequenceKeypoint.new(1, tint:Lerp(Color3.new(0.01, 0.01, 0.035), 0.78)),\n\t})\n\tgradient.Rotation = 32\n\tgradient.Parent = body\n\tfor index = 1, 4 do\n\t\tlocal band = circle(body, ringed and \"CloudBand\" or \"MoonCrater\", ringed and 0.35 or (0.1 + index * 0.023), UDim2.fromScale(0.36 + (index % 2) * 0.18, 0.22 + index * 0.13), tint:Lerp(secondary, 0.45), 0.64)\n\t\tif ringed then band.Size = UDim2.fromScale(0.48, 0.065); band.Rotation = -15 end\n\t\tband.ZIndex = 3\n\tend\n\tlocal ringRoot\n\tif ringed then\n\t\tringRoot = Instance.new(\"Frame\")\n\t\tringRoot.Name = \"PlanetRings\"\n\t\tringRoot.Size = UDim2.fromScale(1, 1)\n\t\tringRoot.AnchorPoint = Vector2.new(0.5, 0.5)\n\t\tringRoot.Position = UDim2.fromScale(0.5, 0.5)\n\t\tringRoot.BackgroundTransparency = 1\n\t\tringRoot.Parent = billboard\n\t\t-- Ring segments are lightweight UI quads, split behind/in front of the\n\t\t-- shaded disc. They stay inside this world-space billboard, never UI.\n\t\tfor band = 1, 2 do\n\t\t\tlocal radiusX = band == 1 and 0.445 or 0.485\n\t\t\tlocal radiusY = band == 1 and 0.15 or 0.175\n\t\t\tfor index = 0, 31 do\n\t\t\t\tlocal angle = index / 32 * math.pi * 2\n\t\t\t\tlocal segment = Instance.new(\"Frame\")\n\t\t\t\tsegment.Name = \"PlanetRingSegment\"\n\t\t\t\tsegment.AnchorPoint = Vector2.new(0.5, 0.5)\n\t\t\t\tsegment.Position = UDim2.fromScale(0.5 + math.cos(angle) * radiusX, 0.5 + math.sin(angle) * radiusY)\n\t\t\t\tlocal length = math.sqrt((math.sin(angle) * radiusX) ^ 2 + (math.cos(angle) * radiusY) ^ 2) * math.pi / 16 * 1.06\n\t\t\t\tsegment.Size = UDim2.fromScale(length, band == 1 and 0.014 or 0.007)\n\t\t\t\tsegment.Rotation = math.deg(math.atan2(math.cos(angle) * radiusY, -math.sin(angle) * radiusX))\n\t\t\t\tsegment.BackgroundColor3 = secondary:Lerp(WHITE, band * 0.19)\n\t\t\t\tsegment.BackgroundTransparency = band == 1 and 0.22 or 0.45\n\t\t\t\tsegment.BorderSizePixel = 0\n\t\t\t\tsegment.ZIndex = math.sin(angle) >= 0 and 4 or 1\n\t\t\t\tsegment.Parent = ringRoot\n\t\t\tend\n\t\tend\n\tend\n\tlocal satellite = anchor(object, \"OrbitingMoon\", position)\n\t-- Its path is deliberately orbital, so only the main celestial anchor has\n\t-- a FixedWorldPosition invariant.\n\tsatellite:SetAttribute(\"FixedWorldPosition\", nil)\n\tlocal satelliteBillboard = planetBillboard(satellite, \"OrbitingMoonDisc\", diameter * 0.14)\n\tlocal satelliteFace = circle(satelliteBillboard, \"MoonFace\", 0.9, UDim2.fromScale(0.5, 0.5), WHITE)\n\tlocal satelliteGradient = Instance.new(\"UIGradient\")\n\tsatelliteGradient.Color = ColorSequence.new(secondary:Lerp(WHITE, 0.55), tint)\n\tsatelliteGradient.Rotation = 35\n\tsatelliteGradient.Parent = satelliteFace\n\treturn { anchor = object, position = position, body = body, glow = glow, satellite = satellite, size = diameter, tint = tint, ringRoot = ringRoot, gradient = gradient }\nend\n\nlocal function addAdminBeams(parent)\n\tlocal object = anchor(parent, \"RealityPrismAnchor\", Vector3.new(-450, 1200, -3000))\n\tlocal beams = {}\n\tfor index = 1, 3 do\n\t\tlocal from = attachment(object, \"PrismStart\", Vector3.new(-1250, index * 130, index * 95), Vector3.new(1, 0.65, 0).Unit)\n\t\tlocal to = attachment(object, \"PrismEnd\", Vector3.new(1250, index * 100, index * 95), Vector3.new(1, -0.65, 0).Unit)\n\t\tbeams[index] = beam(object, \"RealityBeam\", from, to, Color3.fromHSV(index / 3, 0.6, 1), 28, 800)\n\t\tbeams[index].Transparency = NumberSequence.new(0.58)\n\tend\n\treturn beams\nend\n\nfunction Celestial.Start(runtime, eventId, startedAt, isCurrent, context)\n\tcontext = context or {}\n\tlocal quality = math.clamp(context.qualityScale or 1, 0.35, 1)\n\tlocal intensity = math.clamp(context.intensity or 1, 0.35, 1)\n\tlocal supported = eventId == \"BloodMoon\" or eventId == \"Rainbow\" or eventId == \"Aurora\" or eventId == \"Void\" or eventId == \"AdminAbuse\" or eventId == \"MeteorShower\" or eventId == \"SpiritNight\"\n\tif not supported then return function() end end\n\tlocal folder = Instance.new(\"Folder\")\n\tfolder.Name = \"CelestialEffects\"\n\tfolder:SetAttribute(\"WorldSpace\", true)\n\tfolder:SetAttribute(\"QualityScale\", quality)\n\tfolder:SetAttribute(\"AnimationHz\", 15)\n\tfolder.Parent = runtime\n\tlocal stars, halos, ribbons, adminBeams = {}, {}, {}, {}\n\tlocal planets = {}\n\tlocal moonSnapshots = {}\n\tlocal connection, destroyConnection, skyConnection\n\tlocal cleaned = false\n\tlocal function hideNormalMoon(sky)\n\t\tif sky:IsA(\"Sky\") then\n\t\t\tmoonSnapshots[sky] = sky.MoonAngularSize\n\t\t\tsky.MoonAngularSize = 0\n\t\tend\n\tend\n\tlocal function cleanup()\n\t\tif cleaned then return end\n\t\tcleaned = true\n\t\tif connection then connection:Disconnect() end\n\t\tif destroyConnection then destroyConnection:Disconnect() end\n\t\tif skyConnection then skyConnection:Disconnect() end\n\t\tfor sky, size in pairs(moonSnapshots) do\n\t\t\tif sky.Parent then sky.MoonAngularSize = size end\n\t\tend\n\t\tfolder:Destroy()\n\tend\n\n\tif eventId == \"BloodMoon\" then\n\t\thalos = addBloodMoon(folder)\n\t\tstars = addStars(folder, quality * 0.4, Color3.fromRGB(244, 152, 143), 7259)\n\t\tfor _, sky in ipairs(Lighting:GetChildren()) do hideNormalMoon(sky) end\n\t\tskyConnection = Lighting.ChildAdded:Connect(hideNormalMoon)\n\telseif eventId == \"Rainbow\" then\n\t\taddRainbow(folder)\n\telseif eventId == \"Aurora\" then\n\t\tribbons = addAurora(folder, quality)\n\t\tstars = addStars(folder, quality, Color3.fromRGB(149, 219, 255), 7311)\n\telseif eventId == \"Void\" or eventId == \"AdminAbuse\" then\n\t\tlocal admin = eventId == \"AdminAbuse\"\n\t\tstars = addStars(folder, quality, Color3.fromRGB(199, 158, 255), 7369)\n\t\tplanets[1] = addPlanet(folder, admin and \"AdminPlanet\" or \"VoidPlanet\", admin and POSITIONS.AdminPlanet or POSITIONS.VoidPlanet, admin and 680 or 930, Color3.fromRGB(79, 40, 150), Color3.fromRGB(183, 115, 255), true)\n\t\tif not admin then\n\t\t\tplanets[2] = addPlanet(folder, \"VoidMoon\", POSITIONS.VoidMoon, 820, Color3.fromRGB(67, 98, 162), Color3.fromRGB(134, 215, 252), false)\n\t\telse\n\t\t\taddRainbow(folder)\n\t\t\tadminBeams = addAdminBeams(folder)\n\t\tend\n\t\tfor index = 1, quality < 0.55 and 1 or 2 do\n\t\t\tlocal nebula = part(folder, \"NebulaAnchor\", Vector3.new(-2800 + index * 1600, 2650, -7500), Vector3.new(1600, 350, 200), WHITE, 1)\n\t\t\tnebula:SetAttribute(\"FixedWorldPosition\", nebula.Position)\n\t\t\tsoftEmitter(nebula, \"CosmicNebula\", index == 1 and Color3.fromRGB(169, 70, 237) or Color3.fromRGB(66, 130, 226), 850, 2.5 * quality * intensity)\n\t\tend\n\telseif eventId == \"MeteorShower\" then\n\t\tstars = addStars(folder, quality, Color3.fromRGB(192, 218, 255), 7411)\n\telseif eventId == \"SpiritNight\" then\n\t\tstars = addStars(folder, quality * 0.55, Color3.fromRGB(177, 243, 233), 7507)\n\tend\n\n\tlocal function update(now)\n\t\tlocal elapsed = math.max(0, now - startedAt)\n\t\tfor _, star in ipairs(stars) do\n\t\t\tlocal pulse = 0.5 + 0.5 * math.sin(elapsed * 0.63 + star.phase)\n\t\t\tstar.glint.BackgroundTransparency = 0.12 + 0.28 * pulse\n\t\t\tstar.halo.BackgroundTransparency = 0.78 + 0.14 * pulse\n\t\tend\n\t\tfor index, halo in ipairs(halos) do\n\t\t\thalo.BackgroundTransparency = math.clamp(0.96 - index * 0.009 + math.sin(elapsed * 0.38) * 0.018 * intensity, 0, 1)\n\t\tend\n\t\tfor row, ribbon in ipairs(ribbons) do\n\t\t\tlocal phase = elapsed * 0.2 + row * 0.72\n\t\t\tribbon.points[1].Position = Vector3.new(-1500, row * 75 + math.sin(phase) * 65, row * 95)\n\t\t\tribbon.points[2].Position = Vector3.new(1500, row * 75 + math.cos(phase) * 65, row * 95 + 80)\n\t\t\tribbon.points[1].Axis = Vector3.new(1, math.sin(phase * 0.8 + row) * 0.85, 0.08).Unit\n\t\t\tribbon.points[2].Axis = Vector3.new(1, math.cos(phase * 0.8 + row) * 0.85, -0.08).Unit\n\t\t\tfor layer, band in ipairs(ribbon.beams) do\n\t\t\t\tlocal width = layer == 1 and 125 or 235\n\t\t\t\tband.Width0 = width + math.sin(phase) * 25\n\t\t\t\tband.Width1 = width + math.cos(phase) * 25\n\t\t\t\tband.CurveSize0 = 1050 + math.sin(phase * 0.6) * 180\n\t\t\t\tband.CurveSize1 = 1050 + math.cos(phase * 0.6) * 180\n\t\t\tend\n\t\tend\n\t\tfor index, planet in ipairs(planets) do\n\t\t\tlocal angle = elapsed * 0.028 + index * 1.7\n\t\t\tlocal orbit = Vector3.new(math.cos(angle) * planet.size * 0.92, math.sin(angle) * planet.size * 0.34, math.sin(angle) * planet.size * 0.6)\n\t\t\tplanet.satellite.Position = planet.position + orbit\n\t\t\tplanet.glow.BackgroundTransparency = 0.91 + math.sin(elapsed * 0.35 + index) * 0.025\n\t\t\tplanet.gradient.Rotation = 32 + math.sin(elapsed * 0.04) * 16\n\t\t\tif planet.ringRoot then planet.ringRoot.Rotation = -22 + math.sin(elapsed * 0.025 + index) * 9 end\n\t\t\tif eventId == \"AdminAbuse\" then planet.body.BackgroundColor3 = Color3.fromHSV((elapsed * 0.025 + index * 0.2) % 1, 0.28, 1) end\n\t\tend\n\t\tfor index, prism in ipairs(adminBeams) do\n\t\t\tprism.Color = ColorSequence.new(Color3.fromHSV((elapsed * 0.04 + index / 3) % 1, 0.64, 1))\n\t\t\tprism.CurveSize0 = 800 + math.sin(elapsed * 0.3 + index) * 220\n\t\t\tprism.CurveSize1 = 800 + math.cos(elapsed * 0.3 + index) * 220\n\t\tend\n\tend\n\n\tupdate(workspace:GetServerTimeNow())\n\tif #stars > 0 or #halos > 0 or #ribbons > 0 or #planets > 0 or #adminBeams > 0 then\n\t\tlocal accumulated = 0\n\t\tconnection = RunService.Heartbeat:Connect(function(delta)\n\t\t\tif not runtime.Parent or not isCurrent() then cleanup() return end\n\t\t\taccumulated += delta\n\t\t\tif accumulated < ANIMATION_STEP then return end\n\t\t\taccumulated %= ANIMATION_STEP\n\t\t\tupdate(workspace:GetServerTimeNow())\n\t\tend)\n\tend\n\tdestroyConnection = runtime.Destroying:Connect(cleanup)\n\treturn cleanup\nend\n\nreturn Celestial\n"}, {"path": ["ReplicatedStorage", "Shared", "WeatherEnvironmentEffects"], "class": "ModuleScript", "source": "-- Cosmetic weather accents. Cells and strikes are anchored in the world; the\n-- player only chooses which fixed cells are rendered. No map part is modified.\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Lighting = game:GetService(\"Lighting\")\n\nlocal Environment = {}\nlocal SMOKE = \"rbxasset://textures/particles/smoke_main.dds\"\nlocal SPARK = \"rbxasset://textures/particles/sparkles_main.dds\"\nlocal BIOMES = {\"Meadow\", \"Forest\", \"Jungle\", \"Desert\", \"Snow\", \"Volcano\", \"Ocean\", \"AncientRuins\", \"MagicalForest\", \"Sky\", \"Prehistoric\", \"Mythical\"}\nlocal PALETTE = {Color3.fromRGB(255, 93, 126), Color3.fromRGB(255, 212, 91), Color3.fromRGB(117, 255, 166), Color3.fromRGB(91, 204, 255), Color3.fromRGB(196, 128, 255)}\n\nlocal function part(parent, name, size, position, color, transparency)\n\tlocal p = Instance.new(\"Part\")\n\tp.Name = name; p.Size = size; p.Position = position\n\tp.Color = color or Color3.new(1, 1, 1); p.Transparency = transparency or 1\n\tp.Material = Enum.Material.Neon\n\tp.Anchored = true; p.CanCollide = false; p.CanTouch = false; p.CanQuery = false; p.CastShadow = false\n\tp.Parent = parent\n\treturn p\nend\n\nlocal function particle(parent, name, color, rate, size, lifetime, speed, smoky)\n\tlocal e = Instance.new(\"ParticleEmitter\")\n\te.Name = name; e.Texture = smoky and SMOKE or SPARK\n\te.Color = typeof(color) == \"ColorSequence\" and color or ColorSequence.new(color)\n\te.Rate = rate; e.Lifetime = NumberRange.new(lifetime * 0.7, lifetime)\n\te.Speed = NumberRange.new(speed * 0.4, speed)\n\te.Size = NumberSequence.new({NumberSequenceKeypoint.new(0, size * 0.45), NumberSequenceKeypoint.new(0.25, size), NumberSequenceKeypoint.new(1, size * (smoky and 1.7 or 0))})\n\te.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, smoky and 0.89 or 0.28), NumberSequenceKeypoint.new(0.75, smoky and 0.93 or 0.5), NumberSequenceKeypoint.new(1, 1)})\n\te.LightEmission = smoky and 0.15 or 0.8; e.LightInfluence = smoky and 0.35 or 0\n\te.Rotation = NumberRange.new(-180, 180); e.RotSpeed = NumberRange.new(-20, 20)\n\te.SpreadAngle = Vector2.new(70, 70); e.LockedToPart = false\n\te.Parent = parent\n\treturn e\nend\n\nlocal function focusPosition()\n\tlocal player = Players.LocalPlayer\n\tlocal root = player and player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\treturn root and root.Position or Vector3.new(-338, 12, 248)\nend\n\nfunction Environment.Start(runtime, eventId, startedAt, isCurrent, context)\n\tcontext = context or {}\n\tlocal scale = math.clamp((context.qualityScale or 1) * (context.intensity or 1), 0.15, 1)\n\tlocal cellLimit = math.clamp(math.floor(6 * scale + 0.5), 2, 6)\n\tlocal seed = math.floor(startedAt * 1000) % 2147483647\n\tlocal folder = Instance.new(\"Folder\"); folder.Name = \"WeatherEnvironment\"; folder.Parent = runtime\n\tfolder:SetAttribute(\"CellLimit\", cellLimit); folder:SetAttribute(\"UpdateHz\", 20)\n\tfolder:SetAttribute(\"WorldSpace\", true); folder:SetAttribute(\"EventId\", eventId)\n\tlocal cells, bursts = {}, {}\n\tlocal connection, destroying, flashEffect\n\tlocal live = true\n\tlocal nextCells, lastAction, flashUntil = 0, -1, 0\n\tlocal worldGround = workspace:FindFirstChild(\"AnimalKingdomConcreteGround\") or workspace:FindFirstChild(\"GrassFloor\")\n\tif worldGround and not worldGround:IsA(\"BasePart\") then worldGround = nil end\n\tlocal center = worldGround and worldGround.Position or Vector3.new(-338, 8, 248)\n\tlocal extent = worldGround and worldGround.Size * 0.5 or Vector3.new(650, 1, 650)\n\tlocal surfaces = {}\n\tif worldGround then table.insert(surfaces, worldGround) end\n\tfor _, id in ipairs(BIOMES) do\n\t\tlocal root = workspace:FindFirstChild(id)\n\t\tlocal floor = root and root:FindFirstChild(id .. \"Floor\")\n\t\tif floor and floor:IsA(\"BasePart\") then table.insert(surfaces, floor) end\n\tend\n\tif #surfaces == 0 then table.insert(surfaces, workspace.Terrain) end\n\tlocal surfaceQuery = RaycastParams.new()\n\tsurfaceQuery.FilterType = Enum.RaycastFilterType.Include; surfaceQuery.FilterDescendantsInstances = surfaces\n\tsurfaceQuery.RespectCanCollide = true\n\tlocal clearQuery = RaycastParams.new(); clearQuery.FilterType = Enum.RaycastFilterType.Exclude\n\tclearQuery.RespectCanCollide = true\n\tlocal floorCache = {}\n\tlocal function grounded(x, z, open)\n\t\tif math.abs(x - center.X) > extent.X - 35 or math.abs(z - center.Z) > extent.Z - 35 then return nil end\n\t\tlocal hit = workspace:Raycast(Vector3.new(x, center.Y + 1400, z), Vector3.new(0, -1800, 0), surfaceQuery)\n\t\tif not hit or hit.Normal.Y < 0.9 then return nil end\n\t\tif open then\n\t\t\tlocal excluded = {runtime}\n\t\t\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\t\t\tif player.Character then table.insert(excluded, player.Character) end\n\t\t\tend\n\t\t\tclearQuery.FilterDescendantsInstances = excluded\n\t\t\tlocal top = workspace:Raycast(hit.Position + Vector3.new(0, 180, 0), Vector3.new(0, -184, 0), clearQuery)\n\t\t\tif not top or not table.find(surfaces, top.Instance) then return nil end\n\t\tend\n\t\treturn hit.Position\n\tend\n\tlocal function randomFor(index, salt)\n\t\treturn Random.new((seed + index * 104729 + salt) % 2147483647)\n\tend\n\tlocal function cue(name, position, options)\n\t\tif context.audio then context.audio:PlayCue(name, position, options) end\n\tend\n\tlocal function cleanup()\n\t\tif not live then return end\n\t\tlive = false\n\t\tif connection then connection:Disconnect() end\n\t\tif destroying then destroying:Disconnect() end\n\t\tif flashEffect then flashEffect:Destroy() end\n\t\ttable.clear(cells); table.clear(bursts)\n\t\tfolder:Destroy()\n\tend\n\tdestroying = runtime.Destroying:Connect(cleanup)\n\n\tlocal function addEmitter(cell, name, color, rate, size, life, speed, smoky, acceleration)\n\t\tlocal e = particle(cell.anchor, name, color, rate * scale, size, life, speed, smoky)\n\t\te.Acceleration = acceleration or Vector3.new(2, 0.2, 1)\n\t\ttable.insert(cell.emitters, {emitter = e, rate = e.Rate})\n\t\treturn e\n\tend\n\tlocal function mist(cell, name, color, amount, size)\n\t\treturn addEmitter(cell, name, color, amount, size or 18, 6, 2.5, true, Vector3.new(2.2, 0, 0.8))\n\tend\n\tlocal function orb(cell, index, color, geometric, eyes)\n\t\tlocal r = randomFor(index, cell.key * 241)\n\t\tlocal offset = Vector3.new(r:NextNumber(-28, 28), r:NextNumber(4, 11), r:NextNumber(-28, 28))\n\t\tlocal p = part(cell.anchor, eyes and \"DistantEyes\" or (geometric and \"InvertedGeometry\" or \"DriftingOrb\"), Vector3.one * (eyes and 0.8 or r:NextNumber(0.65, 1.25)), cell.position + offset, color, 0.15)\n\t\tif not geometric then p.Shape = Enum.PartType.Ball end\n\t\tlocal entry = {part = p, origin = cell.position + offset, phase = r:NextNumber(0, 6), eyes = eyes, alpha = 0.15}\n\t\tif eyes then\n\t\t\tlocal right = p:Clone(); right.Name = \"SecondEye\"; right.Parent = cell.anchor\n\t\t\tentry.second = right\n\t\tend\n\t\ttable.insert(cell.orbs, entry)\n\tend\n\tlocal function goldenRay(cell, index)\n\t\tlocal lower = Instance.new(\"Attachment\"); lower.Name = \"GoldenRayFoot\"\n\t\tlower.Position = Vector3.new(index * 17 - 25, 0, 14 - index * 12); lower.Parent = cell.anchor\n\t\tlocal upper = Instance.new(\"Attachment\"); upper.Name = \"GoldenRayCrown\"\n\t\tupper.Position = lower.Position + Vector3.new(13, 44, -7); upper.Parent = cell.anchor\n\t\tlocal beam = Instance.new(\"Beam\"); beam.Name = \"SoftGoldenRay\"\n\t\tbeam.Attachment0 = lower; beam.Attachment1 = upper; beam.Width0 = 1.8; beam.Width1 = 0.45\n\t\tbeam.Color = ColorSequence.new(Color3.fromRGB(255, 226, 139)); beam.LightEmission = 0.7\n\t\tbeam.FaceCamera = true; beam.Segments = 1\n\t\tbeam.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, 0.9), NumberSequenceKeypoint.new(0.8, 0.96), NumberSequenceKeypoint.new(1, 1)})\n\t\tbeam.Parent = cell.anchor\n\tend\n\tlocal function makeCell(key, position)\n\t\tlocal cell = {key = key, position = position, emitters = {}, orbs = {}}\n\t\tcell.anchor = part(folder, \"WorldCell_\" .. key, Vector3.new(100, 0.4, 100), position + Vector3.new(0, 2.4, 0))\n\t\tcell.anchor:SetAttribute(\"WorldOrigin\", position)\n\t\tif eventId == \"SunnySkies\" then\n\t\t\taddEmitter(cell, \"SunlitPollen\", Color3.fromRGB(255, 243, 174), 1.2, 0.26, 6, 0.65, false)\n\t\t\taddEmitter(cell, \"SoftPetals\", Color3.fromRGB(255, 199, 216), 0.3, 0.38, 5, 1.4, false, Vector3.new(2, 0.1, 0))\n\t\telseif eventId == \"RainyDay\" or eventId == \"Thunderstorm\" then\n\t\t\tmist(cell, \"RainGroundMist\", Color3.fromRGB(162, 186, 205), eventId == \"Thunderstorm\" and 1.9 or 1.1, 14)\n\t\t\tlocal splash = addEmitter(cell, \"RainSplashes\", Color3.fromRGB(186, 221, 241), eventId == \"Thunderstorm\" and 9 or 5, 0.55, 0.4, 7, false, Vector3.new(0, -28, 0))\n\t\t\tsplash.EmissionDirection = Enum.NormalId.Top; splash.SpreadAngle = Vector2.new(50, 50)\n\t\t\tcell.anchor.Position = position + Vector3.new(0, 0.22, 0)\n\t\telseif eventId == \"Snowfall\" then\n\t\t\tmist(cell, \"WinterGroundMist\", Color3.fromRGB(207, 231, 251), 1.2, 18)\n\t\t\taddEmitter(cell, \"DriftingSnowGust\", Color3.fromRGB(238, 249, 255), 3.5, 0.45, 4, 6, false, Vector3.new(4, -0.2, 1))\n\t\telseif eventId == \"Foggy\" then\n\t\t\tmist(cell, \"RollingLowFog\", Color3.fromRGB(170, 185, 184), 2.4, 28)\n\t\t\tmist(cell, \"LongMistWisps\", Color3.fromRGB(147, 167, 167), 0.7, 38)\n\t\telseif eventId == \"Windy\" then\n\t\t\tmist(cell, \"WindblownDust\", Color3.fromRGB(183, 165, 119), 1.2, 8)\n\t\t\tlocal debris = addEmitter(cell, \"LeafGlints\", Color3.fromRGB(134, 177, 91), 3, 0.35, 2.8, 14, false, Vector3.new(16, 1, 3))\n\t\t\tdebris.RotSpeed = NumberRange.new(70, 170)\n\t\telseif eventId == \"Heatwave\" then\n\t\t\tmist(cell, \"DryDust\", Color3.fromRGB(232, 193, 120), 0.75, 15)\n\t\t\tlocal shimmer = mist(cell, \"HorizonShimmer\", Color3.fromRGB(255, 227, 174), 0.8, 24)\n\t\t\tshimmer.Acceleration = Vector3.new(0.4, 2.2, 0)\n\t\telseif eventId == \"Aurora\" then\n\t\t\taddEmitter(cell, \"AuroraGroundGlints\", ColorSequence.new(Color3.fromRGB(137, 255, 216), Color3.fromRGB(198, 151, 255)), 1.8, 0.4, 5, 1.8, false)\n\t\telseif eventId == \"BloodMoon\" then\n\t\t\taddEmitter(cell, \"BloodEmbers\", Color3.fromRGB(246, 51, 55), 2.1, 0.4, 5, 2.1, false, Vector3.new(0.8, 1.5, 0))\n\t\t\tmist(cell, \"CrimsonShadowWisps\", Color3.fromRGB(72, 12, 27), 0.9, 20)\n\t\telseif eventId == \"MeteorShower\" then\n\t\t\taddEmitter(cell, \"SettlingMeteorCinders\", Color3.fromRGB(255, 184, 110), 0.8, 0.35, 3.5, 1.2, false, Vector3.new(1, -0.2, 0))\n\t\telseif eventId == \"SpiritNight\" then\n\t\t\tmist(cell, \"SpiritGroundMist\", ColorSequence.new(Color3.fromRGB(65, 219, 185), Color3.fromRGB(157, 112, 234)), 1.5, 20)\n\t\t\taddEmitter(cell, \"LostSoulGlints\", Color3.fromRGB(153, 245, 236), 1.8, 0.5, 5, 2, false)\n\t\telseif eventId == \"Rainbow\" then\n\t\t\taddEmitter(cell, \"RainbowGlitter\", ColorSequence.new({ColorSequenceKeypoint.new(0, PALETTE[1]), ColorSequenceKeypoint.new(0.3, PALETTE[2]), ColorSequenceKeypoint.new(0.6, PALETTE[3]), ColorSequenceKeypoint.new(1, PALETTE[5])}), 2.5, 0.4, 5, 1.7, false)\n\t\telseif eventId == \"Chaos\" or eventId == \"AdminAbuse\" then\n\t\t\taddEmitter(cell, \"RealitySparks\", ColorSequence.new(PALETTE[1], PALETTE[4]), eventId == \"AdminAbuse\" and 4 or 2.5, 0.75, 3, 3, false)\n\t\t\tfor i = 1, eventId == \"AdminAbuse\" and 3 or 2 do orb(cell, i, PALETTE[(key + i) % #PALETTE + 1], false) end\n\t\t\tlocal precipitation = part(cell.anchor, \"RealityPrecipitationVolume\", Vector3.new(80, 1, 80), position + Vector3.new(0, 28, 0))\n\t\t\tprecipitation:SetAttribute(\"WorldOrigin\", position + Vector3.new(0, 28, 0))\n\t\t\tlocal rain = addEmitter(cell, \"RealityRain\", Color3.fromRGB(143, 204, 255), 7, 0.45, 1.5, 15, false, Vector3.new(0, -24, 0))\n\t\t\train.Parent = precipitation; rain.EmissionDirection = Enum.NormalId.Bottom\n\t\t\train.SpreadAngle = Vector2.new(10, 10)\n\t\t\train.Enabled = false\n\t\t\tlocal snow = addEmitter(cell, \"RealitySnow\", Color3.new(1, 1, 1), 4, 0.7, 3, 3, false, Vector3.new(5, -1.5, 0))\n\t\t\tsnow.Parent = precipitation; snow.EmissionDirection = Enum.NormalId.Bottom\n\t\t\tsnow.SpreadAngle = Vector2.new(25, 25)\n\t\t\tsnow.Enabled = false\n\t\telseif eventId == \"Inverted\" then\n\t\t\taddEmitter(cell, \"InvertedWhiteFlecks\", Color3.new(1, 1, 1), 1.4, 0.7, 4, 1, false, Vector3.new(0, 2, 0))\n\t\t\tlocal black = addEmitter(cell, \"InvertedBlackFlecks\", Color3.new(0, 0, 0), 1.4, 0.7, 4, 1, false, Vector3.new(0, -1, 0))\n\t\t\tblack.LightEmission = 0\n\t\t\tfor i = 1, 3 do orb(cell, i, i % 2 == 0 and Color3.new(1, 1, 1) or Color3.fromRGB(8, 6, 16), true) end\n\t\telseif eventId == \"Nightmare\" then\n\t\t\tmist(cell, \"CrawlingShadowMist\", Color3.fromRGB(28, 9, 38), 1.3, 24)\n\t\t\taddEmitter(cell, \"BlackAsh\", Color3.fromRGB(25, 11, 32), 1.7, 0.8, 4, 2, false)\n\t\t\torb(cell, 1, Color3.fromRGB(243, 62, 86), false, true)\n\t\telseif eventId == \"Void\" then\n\t\t\tmist(cell, \"GroundNebula\", Color3.fromRGB(106, 46, 175), 1.3, 22)\n\t\t\taddEmitter(cell, \"CosmicDust\", Color3.fromRGB(187, 127, 255), 2.3, 0.5, 6, 2.5, false)\n\t\t\tfor i = 1, 2 do orb(cell, i, Color3.fromRGB(169, 97, 255), false) end\n\t\telseif eventId == \"Golden\" then\n\t\t\taddEmitter(cell, \"GoldenDust\", ColorSequence.new(Color3.fromRGB(255, 219, 104), Color3.fromRGB(255, 248, 202)), 3, 0.48, 5.5, 1.4, false)\n\t\t\tmist(cell, \"WarmGoldHaze\", Color3.fromRGB(255, 219, 113), 0.35, 16)\n\t\t\tfor i = 1, scale > 0.55 and 2 or 1 do goldenRay(cell, i) end\n\t\tend\n\t\treturn cell\n\tend\n\tlocal function selectCells(now)\n\t\tlocal focus = focusPosition()\n\t\tlocal gx, gz = math.floor((focus.X - center.X) / 110 + 0.5), math.floor((focus.Z - center.Z) / 110 + 0.5)\n\t\tlocal candidates = {}\n\t\tfor dx = -2, 2 do\n\t\t\tfor dz = -2, 2 do\n\t\t\t\tlocal x, z = gx + dx, gz + dz\n\t\t\t\tlocal key = (x + 32) * 128 + z + 32\n\t\t\t\tlocal cached = floorCache[key]\n\t\t\t\tif cached == nil then\n\t\t\t\t\tcached = grounded(center.X + x * 110, center.Z + z * 110, true) or false\n\t\t\t\t\tfloorCache[key] = cached\n\t\t\t\tend\n\t\t\t\tif cached then\n\t\t\t\t\tlocal distance = (Vector3.new(focus.X, cached.Y, focus.Z) - cached).Magnitude\n\t\t\t\t\tif cells[key] then distance -= 25 end -- hysteresis prevents boundary flicker\n\t\t\t\t\ttable.insert(candidates, {key = key, position = cached, distance = distance})\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\ttable.sort(candidates, function(a, b) return a.distance < b.distance end)\n\t\tlocal wanted = {}\n\t\tfor i = 1, math.min(cellLimit, #candidates) do wanted[candidates[i].key] = candidates[i].position end\n\t\tfor key, cell in pairs(cells) do\n\t\t\tif not wanted[key] then cell.anchor:Destroy(); cells[key] = nil end\n\t\tend\n\t\tfor key, position in pairs(wanted) do if not cells[key] then cells[key] = makeCell(key, position) end end\n\t\tlocal activeCells = 0\n\t\tfor _ in pairs(cells) do activeCells += 1 end\n\t\tfolder:SetAttribute(\"ActiveCells\", activeCells)\n\t\tnextCells = now + 2\n\tend\n\n\tlocal function safeStrike(index)\n\t\tlocal r = randomFor(index, 8631)\n\t\tfor _ = 1, 12 do\n\t\t\tlocal position = grounded(center.X + r:NextNumber(-extent.X + 55, extent.X - 55), center.Z + r:NextNumber(-extent.Z + 55, extent.Z - 55), true)\n\t\t\tif position then\n\t\t\t\tlocal safe = true\n\t\t\t\tfor _, player in ipairs(Players:GetPlayers()) do\n\t\t\t\t\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\t\t\t\tif root and (root.Position - position).Magnitude < 45 then safe = false; break end\n\t\t\t\tend\n\t\t\t\tif safe then return position end\n\t\t\tend\n\t\tend\n\t\treturn nil\n\tend\n\tlocal function burst(position, color, now, fire, ring)\n\t\tif #bursts >= 4 then return end\n\t\tlocal anchor = part(folder, fire and \"HarmlessFireBurst\" or \"MagicStarBurst\", Vector3.one, position + Vector3.new(0, 0.3, 0))\n\t\tlocal sparks = particle(anchor, \"BurstSparks\", color, 0, fire and 1.4 or 0.8, 1.6, fire and 28 or 14, false)\n\t\tsparks.Acceleration = Vector3.new(0, -14, 0); sparks:Emit(math.floor(32 * scale))\n\t\tlocal smoke = particle(anchor, fire and \"FireSteam\" or \"MagicMist\", fire and Color3.fromRGB(154, 131, 110) or color, 0, 7, 3.5, 8, true)\n\t\tsmoke.Acceleration = Vector3.new(0, 4, 0); smoke:Emit(math.floor(12 * scale))\n\t\tif fire then\n\t\t\tlocal flame = particle(anchor, \"FlameBurst\", ColorSequence.new(Color3.fromRGB(255, 232, 134), Color3.fromRGB(255, 79, 31)), 0, 4, 1.1, 12, false)\n\t\t\tflame.Texture = \"rbxasset://textures/particles/fire_main.dds\"\n\t\t\tflame.Acceleration = Vector3.new(0, 12, 0); flame:Emit(math.floor(24 * scale))\n\t\tend\n\t\tlocal light = Instance.new(\"PointLight\"); light.Color = color; light.Range = fire and 35 or 20; light.Brightness = 1.3; light.Parent = anchor\n\t\tlocal rings = {}\n\t\tif ring then\n\t\t\tfor i = 1, 10 do\n\t\t\t\tlocal p = part(anchor, \"CosmeticShockwave\", Vector3.new(1, 0.12, 0.3), position, color, 0.3)\n\t\t\t\ttable.insert(rings, {part = p, angle = i / 10 * math.pi * 2})\n\t\t\tend\n\t\tend\n\t\ttable.insert(bursts, {part = anchor, at = now, light = light, rings = rings, position = position, lifetime = 4})\n\t\tif fire then cue(\"FireBurst\", position) end\n\tend\n\tlocal function lightning(index, now, color, energy)\n\t\tif #bursts >= 4 then return end\n\t\tlocal position = safeStrike(index)\n\t\tif not position then return end\n\t\tlocal r = randomFor(index, 451)\n\t\tlocal anchor = part(folder, energy and \"WorldEnergyStrike\" or \"WorldLightning\", Vector3.one, position)\n\t\tanchor:SetAttribute(\"StrikePosition\", position)\n\t\tlocal previous\n\t\tlocal beamList = {}\n\t\tfor i = 0, 8 do\n\t\t\tlocal a = Instance.new(\"Attachment\"); a.Name = \"BoltNode\" .. i\n\t\t\ta.Position = i == 8 and Vector3.zero or Vector3.new(r:NextNumber(-24, 24), (8 - i) * 66, r:NextNumber(-24, 24))\n\t\t\ta.Parent = anchor\n\t\t\tif previous then\n\t\t\t\tlocal beam = Instance.new(\"Beam\"); beam.Name = \"LightningBolt\"\n\t\t\t\tbeam.Attachment0 = previous; beam.Attachment1 = a\n\t\t\t\tbeam.Color = ColorSequence.new(color); beam.Width0 = 2.4; beam.Width1 = 1.9\n\t\t\t\tbeam.LightEmission = 1; beam.LightInfluence = 0; beam.FaceCamera = true; beam.Segments = 1\n\t\t\t\tbeam.Transparency = NumberSequence.new(0); beam.Parent = anchor\n\t\t\t\ttable.insert(beamList, beam)\n\t\t\tend\n\t\t\tprevious = a\n\t\tend\n\t\ttable.insert(bursts, {part = anchor, at = now, beams = beamList, lifetime = 0.75})\n\t\tburst(position, color, now, false, true)\n\t\tif not flashEffect then\n\t\t\tflashEffect = Instance.new(\"ColorCorrectionEffect\"); flashEffect.Name = \"AK_WeatherLightningFlash\"\n\t\t\tflashEffect:SetAttribute(\"WeatherTemporary\", true); flashEffect.Parent = Lighting\n\t\tend\n\t\tflashEffect.TintColor = Color3.new(1, 1, 1):Lerp(color, 0.12)\n\t\tflashEffect.Brightness = eventId == \"Nightmare\" and 0.075 or 0.15\n\t\tflashUntil = now + 0.32\n\t\tlocal distance = (focusPosition() - position).Magnitude\n\t\t-- The audio controller owns the speed-of-sound delay, so it is applied once.\n\t\tcue(energy and \"EnergyStrike\" or (distance > 650 and \"ThunderDistant\" or \"ThunderStrike\"), position)\n\tend\n\tlocal function nearbyPosition(index)\n\t\tlocal ordered = {}\n\t\tfor _, cell in pairs(cells) do table.insert(ordered, cell) end\n\t\ttable.sort(ordered, function(a, b) return a.key < b.key end)\n\t\tif #ordered == 0 then return nil end\n\t\treturn ordered[index % #ordered + 1].position\n\tend\n\tlocal interval = ({Thunderstorm = 8.5, Windy = 7, Snowfall = 10, Heatwave = 13, BloodMoon = 12, Aurora = 13, Rainbow = 11, Golden = 7, SpiritNight = 13, Chaos = 5, AdminAbuse = 3.7, Nightmare = 16, Void = 12, RainyDay = 15, Inverted = 13})[eventId] or 18\n\tlocal function action(index, now)\n\t\tlocal position = nearbyPosition(index)\n\t\tif eventId == \"Thunderstorm\" then lightning(index, now, Color3.fromRGB(190, 219, 255), false)\n\t\telseif eventId == \"Nightmare\" then lightning(index, now, Color3.fromRGB(245, 71, 101), false)\n\t\telseif eventId == \"Void\" then lightning(index, now, Color3.fromRGB(174, 108, 255), true)\n\t\telseif eventId == \"Chaos\" or eventId == \"AdminAbuse\" then\n\t\t\tlocal stage = index % 4\n\t\t\tfolder:SetAttribute(\"CombinationStage\", stage)\n\t\t\tif stage == 0 then lightning(index, now, PALETTE[index % #PALETTE + 1], false)\n\t\t\telseif stage == 1 then local target = safeStrike(index); if target then burst(target, Color3.fromRGB(255, 160, 69), now, true, true) end\n\t\t\telseif stage == 2 and position then burst(position, PALETTE[index % #PALETTE + 1], now, false, true); cue(\"MagicBurst\", position)\n\t\t\telseif stage == 3 then lightning(index, now, Color3.fromRGB(183, 121, 255), true) end\n\t\telseif position and (eventId == \"Windy\" or eventId == \"Snowfall\" or eventId == \"Heatwave\") then\n\t\t\tfolder:SetAttribute(\"GustAt\", now); cue(\"WindGust\", position)\n\t\t\tfor _, cell in pairs(cells) do\n\t\t\t\tfor _, entry in ipairs(cell.emitters) do entry.emitter:Emit(math.floor(8 * scale)) end\n\t\t\tend\n\t\telseif position and (eventId == \"Golden\" or eventId == \"Rainbow\" or eventId == \"Aurora\") then\n\t\t\tlocal color = eventId == \"Golden\" and Color3.fromRGB(255, 221, 126) or (eventId == \"Aurora\" and Color3.fromRGB(151, 255, 219) or PALETTE[index % #PALETTE + 1])\n\t\t\tburst(position + Vector3.new(0, 5, 0), color, now, false, false)\n\t\t\tcue(eventId == \"Golden\" and \"StarBurst\" or \"MagicBurst\", position)\n\t\telseif position and eventId == \"RainyDay\" then cue(\"WaterSplash\", position)\n\t\telseif position and eventId == \"Inverted\" then\n\t\t\tburst(position + Vector3.new(0, 5, 0), Color3.fromRGB(175, 245, 223), now, false, false)\n\t\t\tcue(\"MagicZap\", position)\n\t\tend\n\tend\n\n\tlocal function update()\n\t\tif not live or runtime.Parent == nil or not isCurrent() then cleanup(); return end\n\t\tlocal now = workspace:GetServerTimeNow()\n\t\tlocal elapsed = math.max(0, now - startedAt)\n\t\tif now >= nextCells then selectCells(now) end\n\t\tlocal index = math.floor((elapsed - 2) / interval)\n\t\tif index >= 0 and index > lastAction then\n\t\t\tlastAction = index\n\t\t\t-- Do not replay an old burst when a late join occurs between action slots.\n\t\t\tif (elapsed - 2) % interval < 1 then action(index, now) end\n\t\tend\n\t\tlocal stage = math.max(0, lastAction) % 4\n\t\tfor _, cell in pairs(cells) do\n\t\t\tfor _, entry in ipairs(cell.orbs) do\n\t\t\t\tlocal phase = elapsed * 0.42 + entry.phase\n\t\t\t\tlocal position = entry.origin + Vector3.new(math.sin(phase) * 5, math.cos(phase * 1.7) * 1.2, math.cos(phase) * 5)\n\t\t\t\tentry.part.CFrame = CFrame.new(position) * CFrame.Angles(phase, phase * 0.7, phase * 0.4)\n\t\t\t\tentry.part.Transparency = entry.eyes and (0.2 + 0.6 * (math.sin(phase * 0.5) * 0.5 + 0.5)) or (0.14 + 0.1 * math.sin(phase))\n\t\t\t\tif entry.second then entry.second.Position = position + Vector3.new(1.8, 0, 0); entry.second.Transparency = entry.part.Transparency end\n\t\t\tend\n\t\t\tfor _, entry in ipairs(cell.emitters) do\n\t\t\t\tlocal emitter = entry.emitter\n\t\t\t\tif emitter.Name == \"RealityRain\" then emitter.Enabled = stage == 0\n\t\t\t\telseif emitter.Name == \"RealitySnow\" then emitter.Enabled = stage == 2\n\t\t\t\telseif eventId == \"BloodMoon\" then emitter.Rate = entry.rate * (0.82 + math.sin(elapsed * 0.7) * 0.18) end\n\t\t\tend\n\t\tend\n\t\tfor i = #bursts, 1, -1 do\n\t\t\tlocal b = bursts[i]; local age = now - b.at\n\t\t\tif age >= b.lifetime then b.part:Destroy(); table.remove(bursts, i)\n\t\t\telse\n\t\t\t\tif b.light then b.light.Brightness = 1.3 * math.max(0, 1 - age / 1.2) end\n\t\t\t\tif b.beams then\n\t\t\t\t\tlocal transparency = age < 0.1 and 0 or (age < 0.16 and 0.8 or math.clamp((age - 0.16) / 0.59, 0, 1))\n\t\t\t\t\tfor _, beam in ipairs(b.beams) do beam.Transparency = NumberSequence.new(transparency) end\n\t\t\t\tend\n\t\t\t\tif b.rings then\n\t\t\t\t\tlocal alpha = math.clamp(age / 0.9, 0, 1)\n\t\t\t\t\tlocal radius = 2 + alpha * 20\n\t\t\t\t\tfor _, ring in ipairs(b.rings) do\n\t\t\t\t\t\tring.part.Size = Vector3.new(radius * 0.64, 0.12, 0.3)\n\t\t\t\t\t\tring.part.CFrame = CFrame.new(b.position + Vector3.new(math.cos(ring.angle) * radius, 0.2, math.sin(ring.angle) * radius)) * CFrame.Angles(0, -ring.angle + math.pi / 2, 0)\n\t\t\t\t\t\tring.part.Transparency = 0.3 + alpha * 0.7\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tif flashEffect then flashEffect.Brightness = math.max(0, (flashUntil - now) / 0.32) * (eventId == \"Nightmare\" and 0.075 or 0.15) end\n\t\tfolder:SetAttribute(\"ActiveBursts\", #bursts)\n\tend\n\tupdate()\n\tlocal accumulator = 0\n\tif live then connection = RunService.Heartbeat:Connect(function(dt)\n\t\taccumulator += dt\n\t\tif accumulator >= 1 / 20 then accumulator = 0; update() end\n\tend) end\n\treturn cleanup\nend\n\nreturn Environment\n"}, {"path": ["ReplicatedStorage", "Shared", "MeteorShowerEffects"], "class": "ModuleScript", "source": "-- Client-rendered, server-clock meteor choreography. Never excavates authored floors.\nlocal RunService = game:GetService(\"RunService\")\nlocal Players = game:GetService(\"Players\")\nlocal Effects = {}\nlocal STEP = 0.48\nlocal BIG_INTERVAL = 14\nlocal FIRST_BIG = 5\nlocal BIG_FLIGHT = 2.25\nlocal IMPACT_LIFETIME = 30\nlocal MAX_METEORS = 18\nlocal BIOMES = {\"Meadow\", \"Forest\", \"Jungle\", \"Desert\", \"Snow\", \"Volcano\", \"Ocean\", \"AncientRuins\", \"MagicalForest\", \"Sky\", \"Prehistoric\", \"Mythical\"}\n\nlocal function part(parent, name, size, cf, tint, material, alpha)\n local p = Instance.new(\"Part\")\n p.Name = name; p.Size = size; p.CFrame = cf; p.Color = tint\n p.Material = material or Enum.Material.Neon; p.Transparency = alpha or 0\n p.Anchored = true; p.CanCollide = false; p.CanTouch = false; p.CanQuery = false; p.CastShadow = false\n p.TopSurface = Enum.SurfaceType.Smooth; p.BottomSurface = Enum.SurfaceType.Smooth\n p.Parent = parent\n return p\nend\n\nlocal function emitter(parent, name, tint, size, life, speed)\n local e = Instance.new(\"ParticleEmitter\")\n e.Name = name; e.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n e.Color = ColorSequence.new(tint); e.LightEmission = 0.85; e.LightInfluence = 0\n e.Size = NumberSequence.new({NumberSequenceKeypoint.new(0, size), NumberSequenceKeypoint.new(1, 0)})\n e.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 1)})\n e.Lifetime = NumberRange.new(life * 0.65, life); e.Speed = NumberRange.new(speed * 0.5, speed)\n e.SpreadAngle = Vector2.new(180, 180); e.Rate = 0; e.Parent = parent\n return e\nend\n\nfunction Effects.Start(runtime, startedAt, isCurrent, context)\n context = context or {}\n local quality = context.qualityScale or 1\n local intensity = context.intensity or 1\n local audio = context.audio\n local mode = context.meteorMode or \"MeteorShower\"\n local step = STEP * (mode == \"Chaos\" and 3 or mode == \"AdminAbuse\" and 1.4 or 1)\n local bigInterval = mode == \"Chaos\" and 28 or BIG_INTERVAL\n local maxMeteors = math.max(5, math.floor(MAX_METEORS * quality))\n local folder = Instance.new(\"Folder\"); folder.Name = \"MeteorShowerEffects\"; folder.Parent = runtime\n folder:SetAttribute(\"ImpactLifetime\", IMPACT_LIFETIME); folder:SetAttribute(\"LargeStrikeInterval\", bigInterval); folder:SetAttribute(\"MeteorLimit\", maxMeteors)\n local ground = workspace:FindFirstChild(\"AnimalKingdomConcreteGround\") or workspace:FindFirstChild(\"GrassFloor\")\n if ground and not ground:IsA(\"BasePart\") then ground = nil end\n local center = ground and ground.Position or Vector3.new(-338, 8, 248)\n local extent = ground and ground.Size * 0.5 or Vector3.new(650, 0, 650)\n local seed = math.floor(startedAt * 1000) % 2147483647\n local flights, impacts, flashes = {}, {}, {}\n local live, connection, destroying = true, nil, nil\n local lastSmall, lastBig = -1, -1\n local function randomFor(index, salt)\n  return Random.new((seed + index * 104729 + salt) % 2147483647)\n end\n local function active() return live and runtime.Parent ~= nil and isCurrent() end\n local function cleanup()\n  if not live then return end\n  live = false\n  if connection then connection:Disconnect() end\n  if destroying then destroying:Disconnect() end\n  table.clear(flights); table.clear(impacts); table.clear(flashes)\n  folder:Destroy()\n end\n destroying = runtime.Destroying:Connect(cleanup)\n\n local function launch(index, big, start, finish, launchAt, duration, size)\n  if #flights >= maxMeteors then return end\n  local meteor = part(folder, big and \"LargeMeteor\" or \"Meteor\", Vector3.one * size,\n   CFrame.lookAt(start, finish), Color3.fromRGB(255, 158, 65), Enum.Material.Neon)\n  meteor.Shape = Enum.PartType.Ball\n  meteor:SetAttribute(\"LaunchAt\", launchAt); meteor:SetAttribute(\"StrikeIndex\", index)\n  meteor:SetAttribute(\"StartPosition\", start); meteor:SetAttribute(\"TargetPosition\", finish)\n  local a = Instance.new(\"Attachment\"); a.Position = Vector3.new(-size * 0.35, 0, 0); a.Parent = meteor\n  local b = Instance.new(\"Attachment\"); b.Position = Vector3.new(size * 0.35, 0, 0); b.Parent = meteor\n  local trail = Instance.new(\"Trail\"); trail.Name = \"FireTrail\"; trail.Attachment0 = a; trail.Attachment1 = b\n  trail.Color = ColorSequence.new(Color3.fromRGB(255, 231, 166), Color3.fromRGB(255, 71, 26))\n  trail.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.05), NumberSequenceKeypoint.new(1, 1)})\n  trail.Lifetime = big and 0.9 or 0.55; trail.MinLength = 0.1; trail.LightEmission = 1; trail.FaceCamera = true; trail.Parent = meteor\n  local fire = emitter(meteor, \"FireSparks\", Color3.fromRGB(255, 131, 44), big and 5 or 1.5, 0.6, big and 12 or 4)\n  fire.Rate = (big and 42 or 8) * quality * intensity\n  local smoke = emitter(meteor, \"SmokeTrail\", Color3.fromRGB(97, 83, 79), big and 6 or 2, big and 1.3 or 0.7, 1)\n  smoke.Texture = \"rbxasset://textures/particles/smoke_main.dds\"; smoke.LightEmission = 0.08\n  smoke.Rate = (big and 14 or 3) * quality * intensity\n  -- Each visible flight requests an appropriately sized cue; the central mixer\n  -- bounds simultaneous voices without making audio depend on graphics quality.\n  if audio then audio:PlayCue(big and \"MeteorFlybyLarge\" or \"MeteorFlybySmall\", meteor) end\n  if big then\n   local rock = part(meteor, \"RockCore\", Vector3.one * (size * 0.74), meteor.CFrame, Color3.fromRGB(59, 39, 31), Enum.Material.Slate)\n   rock.Shape = Enum.PartType.Ball\n   local light = Instance.new(\"PointLight\"); light.Color = Color3.fromRGB(255, 133, 63); light.Range = 45; light.Brightness = 2; light.Parent = meteor\n  end\n  table.insert(flights, {part = meteor, start = start, finish = finish, launchAt = launchAt, duration = duration, big = big})\n end\n\n local function impactTarget(index)\n  local random = randomFor(index, 9187)\n  local surfaces = {}\n  if ground then table.insert(surfaces, ground) end\n  for _,id in ipairs(BIOMES) do\n   local model = workspace:FindFirstChild(id)\n   local floor = model and model:FindFirstChild(id .. \"Floor\")\n   if floor and floor:IsA(\"BasePart\") then table.insert(surfaces, floor) end\n  end\n  if #surfaces == 0 then table.insert(surfaces, workspace.Terrain) end\n  local query = RaycastParams.new(); query.FilterType = Enum.RaycastFilterType.Include; query.FilterDescendantsInstances = surfaces; query.RespectCanCollide = true\n  local clear = RaycastParams.new(); clear.FilterType = Enum.RaycastFilterType.Exclude; clear.RespectCanCollide = true\n  local exclude = {runtime}\n  for _,player in ipairs(Players:GetPlayers()) do if player.Character then table.insert(exclude, player.Character) end end\n  clear.FilterDescendantsInstances = exclude\n  for _ = 1, 12 do\n   local pos = center + Vector3.new(random:NextNumber(-math.max(0, extent.X - 50), math.max(0, extent.X - 50)), 1200, random:NextNumber(-math.max(0, extent.Z - 50), math.max(0, extent.Z - 50)))\n   local hit = workspace:Raycast(pos, Vector3.new(0, -2400, 0), query)\n   if hit and hit.Normal.Y > 0.95 then\n    local open = true\n    -- Leave buildings/tree trunks alone and keep every crater rim on real support.\n    for _,offset in ipairs({Vector3.zero, Vector3.new(16, 0, 0), Vector3.new(-16, 0, 0), Vector3.new(0, 0, 16), Vector3.new(0, 0, -16)}) do\n     local down = workspace:Raycast(hit.Position + offset + Vector3.new(0, 150, 0), Vector3.new(0, -154, 0), clear)\n     if not down or not table.find(surfaces, down.Instance) or math.abs(down.Position.Y - hit.Position.Y) > 1 then open = false; break end\n    end\n    if open then return hit.Position end\n   end\n  end\n  return nil -- skip a blocked strike rather than damage a structure\n end\n\n local function makeImpact(index, position, impactAt, now)\n  if now >= impactAt + IMPACT_LIFETIME then return end\n  local random = randomFor(index, 4701)\n  local model = Instance.new(\"Model\"); model.Name = \"MeteorImpact\"\n  model:SetAttribute(\"ImpactAt\", impactAt); model:SetAttribute(\"ExpiresAt\", impactAt + IMPACT_LIFETIME)\n  model:SetAttribute(\"StrikeIndex\", index); model:SetAttribute(\"WorldPosition\", position); model.Parent = folder\n  local surface = position.Y + 0.045\n  local scorch = part(model, \"ScorchedGround\", Vector3.new(0.08, 28, 28), CFrame.new(position.X, surface, position.Z) * CFrame.Angles(0, 0, math.pi / 2), Color3.fromRGB(31, 28, 30), Enum.Material.Slate, 0.1)\n  scorch.Shape = Enum.PartType.Cylinder\n  local molten = part(model, \"CoolingImpact\", Vector3.new(0.09, 12, 12), CFrame.new(position.X, surface + 0.06, position.Z) * CFrame.Angles(0, 0, math.pi / 2), Color3.fromRGB(255, 99, 27), Enum.Material.Neon, 0.1)\n  molten.Shape = Enum.PartType.Cylinder\n  local rubbleCount = quality < 0.5 and 6 or 12\n  for i = 1, rubbleCount do\n   local angle = i / rubbleCount * math.pi * 2\n   local radius = random:NextNumber(11.7, 13.2)\n   local height = random:NextNumber(1.2, 2.7)\n   part(model, \"CraterRubble\", Vector3.new(random:NextNumber(3, 5), height, random:NextNumber(2, 4)), CFrame.new(position + Vector3.new(math.cos(angle) * radius, height * 0.5 + 0.04, math.sin(angle) * radius)) * CFrame.Angles(0, -angle, 0), Color3.fromRGB(70, 59, 54), Enum.Material.Slate)\n   if i % 2 == 0 then\n    local length = random:NextNumber(5, 9)\n    part(model, \"GroundCrack\", Vector3.new(length, 0.065, 0.32), CFrame.new(position + Vector3.new(math.cos(angle) * 7, 0.13, math.sin(angle) * 7)) * CFrame.Angles(0, -angle, 0), Color3.fromRGB(246, 102, 32), Enum.Material.Neon, 0.1)\n   end\n  end\n  local smoke = emitter(scorch, \"ImpactEmbers\", Color3.fromRGB(255, 139, 60), 0.55, 2, 7)\n  smoke.Acceleration = Vector3.new(0, 6, 0); smoke.Rate = 12 * quality * intensity\n  if now - impactAt < 0.6 then\n   local burst = part(folder, \"ImpactFlash\", Vector3.one * 7, CFrame.new(position + Vector3.new(0, 2, 0)), Color3.fromRGB(255, 187, 80), Enum.Material.Neon, 0.2)\n   burst.Shape = Enum.PartType.Ball\n   table.insert(flashes, {part = burst, at = now})\n   smoke:Emit(math.floor(65 * quality * intensity))\n   if audio then\n    audio:PlayCue(\"MeteorImpactLarge\", position)\n    audio:PlayCue(\"FireBurst\", position)\n   end\n   local ring = part(folder, \"ImpactShockwave\", Vector3.new(0.08, 4, 4), CFrame.new(position + Vector3.new(0, 0.18, 0)) * CFrame.Angles(0, 0, math.pi/2), Color3.fromRGB(255, 195, 120), Enum.Material.Neon, 0.4)\n   ring.Shape = Enum.PartType.Cylinder\n   table.insert(flashes, {part = ring, at = now, ring = true})\n   local fire = emitter(scorch, \"ImpactFire\", Color3.fromRGB(255, 172, 58), 6, 0.7, 20)\n   fire.Texture = \"rbxasset://textures/particles/fire_main.dds\"; fire:Emit(math.floor(25 * quality * intensity))\n   local dust = emitter(scorch, \"ImpactDust\", Color3.fromRGB(167, 139, 112), 3, 1.2, 34)\n   dust.Texture = \"rbxasset://textures/particles/smoke_main.dds\"; dust.Acceleration = Vector3.new(0, -12, 0); dust:Emit(math.floor(35 * quality * intensity))\n  end\n  local parts = {}\n  for _,p in ipairs(model:GetChildren()) do if p:IsA(\"BasePart\") then table.insert(parts, {part = p, alpha = p.Transparency}) end end\n  table.insert(impacts, {model = model, at = impactAt, parts = parts, smoke = smoke, molten = molten})\n end\n\n local function small(index)\n  local random = randomFor(index, 1201)\n  local at = startedAt + index * step\n  for lane = 1, (quality < 0.5 and 1 or 2) do\n   local aim = center + Vector3.new(random:NextNumber(-extent.X * 0.8, extent.X * 0.8), random:NextNumber(110, 280), random:NextNumber(-extent.Z * 0.8, extent.Z * 0.8))\n   local direction = Vector3.new(random:NextNumber(430, 850), -random:NextNumber(65, 150), random:NextNumber(-260, 260))\n   launch(index * 2 + lane, false, aim - direction * 0.5, aim + direction * 0.5, at, random:NextNumber(0.8, 1.3), random:NextNumber(3.5, 7))\n  end\n end\n local function big(index, now)\n  local at = startedAt + FIRST_BIG + index * bigInterval\n  local position = impactTarget(index)\n  if not position then return end\n  local impactAt = at + BIG_FLIGHT\n  if now < impactAt then\n   local random = randomFor(index, 8039)\n   local start = position + Vector3.new(-random:NextNumber(230, 420), 570, random:NextNumber(-170, 170))\n   launch(index, true, start, position + Vector3.new(0, 5, 0), at, BIG_FLIGHT, 13)\n  else makeImpact(index, position, impactAt, now) end\n end\n local accumulator = 0\n local function update()\n  if not active() then cleanup(); return end\n  local now = workspace:GetServerTimeNow()\n  local elapsed = math.max(0, now - startedAt)\n  local smallIndex = math.floor(elapsed / step)\n  if smallIndex > lastSmall then\n   -- Reconstruct only still-visible flight slots after a late join/frame stall.\n   for index = math.max(lastSmall + 1, smallIndex - 2), smallIndex do if quality >= 0.7 or index % (quality < 0.5 and 3 or 2) == 0 then small(index) end end\n   lastSmall = smallIndex\n  end\n  local bigIndex = math.floor((elapsed - FIRST_BIG) / bigInterval)\n  if bigIndex > lastBig then\n   for index = math.max(lastBig + 1, math.ceil((elapsed - FIRST_BIG - BIG_FLIGHT - IMPACT_LIFETIME) / bigInterval), 0), bigIndex do big(index, now) end\n   lastBig = bigIndex\n  end\n  for i = #flights, 1, -1 do\n   local flight = flights[i]\n   local alpha = math.clamp((now - flight.launchAt) / flight.duration, 0, 1)\n   if alpha >= 1 then\n    if flight.big then makeImpact(flight.part:GetAttribute(\"StrikeIndex\"), flight.finish - Vector3.new(0, 5, 0), flight.launchAt + flight.duration, now) end\n    flight.part:Destroy(); table.remove(flights, i)\n   else\n    local p = flight.start:Lerp(flight.finish, alpha)\n    flight.part.CFrame = CFrame.lookAt(p, flight.finish)\n    local core = flight.part:FindFirstChild(\"RockCore\")\n    if core then core.CFrame = flight.part.CFrame * CFrame.Angles(alpha * 8, alpha * 6, alpha * 3) end\n   end\n  end\n  for i = #impacts, 1, -1 do\n   local impact = impacts[i]; local age = now - impact.at\n   if age >= IMPACT_LIFETIME then impact.model:Destroy(); table.remove(impacts, i)\n   else\n    local fade = math.clamp((age - 26) / 4, 0, 1)\n    for _,entry in ipairs(impact.parts) do entry.part.Transparency = entry.alpha + (1 - entry.alpha) * fade end\n    impact.molten.Transparency = math.max(impact.molten.Transparency, math.clamp(age / 12, 0.1, 1))\n    impact.smoke.Enabled = age < 9\n   end\n  end\n  for i = #flashes, 1, -1 do\n   local flash = flashes[i]; local alpha = (now - flash.at) / 0.65\n   if alpha >= 1 then flash.part:Destroy(); table.remove(flashes, i)\n   else\n    flash.part.Size = flash.ring and Vector3.new(0.08, 4 + 75 * alpha, 4 + 75 * alpha) or Vector3.one * (7 + 36 * alpha)\n    flash.part.Transparency = (flash.ring and 0.4 or 0.2) + alpha * (flash.ring and 0.6 or 0.8)\n   end\n  end\n end\n update()\n if live then\n  connection = RunService.Heartbeat:Connect(function(dt) accumulator += dt; if accumulator >= 1/30 then accumulator = 0; update() end end)\n end\n return cleanup\nend\n\nreturn Effects\n"}, {"path": ["ReplicatedStorage", "Shared", "SpiritNightEffects"], "class": "ModuleScript", "source": "-- Client-only, cosmetic visitors for Spirit Night. Ghost paths belong to the\n-- world; the viewer position only chooses which nearby paths are rendered.\n-- Every client evaluates the same path from the authoritative event start.\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal SpiritNightEffects = {}\nlocal MAX_GHOSTS = 12\nlocal UPDATE_STEP = 1 / 30\nlocal SELECTION_STEP = 2\nlocal PARTICLES_PER_GHOST = 11 -- 132/s maximum, plus the existing weather mist.\nlocal BIOMES = {\n\t\"Meadow\", \"Forest\", \"Jungle\", \"Desert\", \"Snow\", \"Volcano\", \"Ocean\",\n\t\"AncientRuins\", \"MagicalForest\", \"Sky\", \"Prehistoric\", \"Mythical\",\n}\n\nlocal function viewerPosition()\n\tlocal player = Players.LocalPlayer\n\tlocal character = player and player.Character\n\tlocal root = character and character:FindFirstChild(\"HumanoidRootPart\")\n\tif root then return root.Position end\n\tlocal camera = workspace.CurrentCamera\n\treturn camera and camera.CFrame.Position or Vector3.new(-338, 15, 248)\nend\n\nlocal function part(model, name, size, offset, tint, transparency, material)\n\tlocal value = Instance.new(\"Part\")\n\tvalue.Name = name\n\tvalue.Shape = Enum.PartType.Ball\n\tvalue.Size = size\n\tvalue.CFrame = offset\n\tvalue.Color = tint\n\tvalue.Material = material or Enum.Material.Neon\n\tvalue.Transparency = transparency\n\tvalue.Anchored = true\n\tvalue.CanCollide = false\n\tvalue.CanTouch = false\n\tvalue.CanQuery = false\n\tvalue.CastShadow = false\n\tvalue.Parent = model\n\treturn value\nend\n\nlocal function emitter(parent, name, rate, smoke, tint)\n\tlocal value = Instance.new(\"ParticleEmitter\")\n\tvalue.Name = name\n\tvalue.Texture = smoke and \"rbxasset://textures/particles/smoke_main.dds\"\n\t\tor \"rbxasset://textures/particles/sparkles_main.dds\"\n\tvalue.Rate = rate\n\tvalue.Lifetime = smoke and NumberRange.new(1.4, 2.2) or NumberRange.new(2, 3.2)\n\tvalue.Speed = smoke and NumberRange.new(0.4, 1.1) or NumberRange.new(1.2, 3)\n\tvalue.Acceleration = Vector3.new(0, smoke and 0.7 or 1.4, 0)\n\tvalue.SpreadAngle = Vector2.new(160, 160)\n\tvalue.Rotation = NumberRange.new(0, 360)\n\tvalue.RotSpeed = NumberRange.new(-35, 35)\n\tvalue.LightEmission = 0.8\n\tvalue.LightInfluence = 0\n\tvalue.LockedToPart = false\n\tvalue.Color = ColorSequence.new(tint, Color3.fromRGB(177, 144, 255))\n\tvalue.Size = smoke and NumberSequence.new({\n\t\tNumberSequenceKeypoint.new(0, 1.3),\n\t\tNumberSequenceKeypoint.new(1, 4),\n\t}) or NumberSequence.new({\n\t\tNumberSequenceKeypoint.new(0, 0),\n\t\tNumberSequenceKeypoint.new(0.2, 0.24),\n\t\tNumberSequenceKeypoint.new(1, 0),\n\t})\n\tvalue.Transparency = NumberSequence.new({\n\t\tNumberSequenceKeypoint.new(0, 1),\n\t\tNumberSequenceKeypoint.new(0.2, smoke and 0.78 or 0.16),\n\t\tNumberSequenceKeypoint.new(0.7, smoke and 0.9 or 0.4),\n\t\tNumberSequenceKeypoint.new(1, 1),\n\t})\n\tvalue.Parent = parent\n\treturn value\nend\n\nlocal function worldPaths(startedAt)\n\tlocal paths = {}\n\tlocal ground = workspace:FindFirstChild(\"AnimalKingdomConcreteGround\")\n\tlocal supports = {}\n\tif ground and ground:IsA(\"BasePart\") then table.insert(supports, ground) end\n\tlocal town = workspace:FindFirstChild(\"TownPlaza\")\n\tif town and town:IsA(\"BasePart\") then table.insert(supports, town) end\n\tfor _, name in ipairs(BIOMES) do\n\t\tlocal biome = workspace:FindFirstChild(name)\n\t\tlocal floor = biome and biome:FindFirstChild(name .. \"Floor\")\n\t\tif floor and floor:IsA(\"BasePart\") then table.insert(supports, floor) end\n\tend\n\t-- The source-only development map has a different footprint from the\n\t-- authored place. Use its actual floor rather than spawning off the map.\n\tif #supports == 0 then\n\t\tlocal floor = workspace:FindFirstChild(\"GrassFloor\")\n\t\tif floor and floor:IsA(\"BasePart\") then\n\t\t\tground = floor\n\t\t\ttable.insert(supports, floor)\n\t\tend\n\tend\n\tif #supports == 0 then return paths end\n\tground = ground or supports[1]\n\tlocal ray = RaycastParams.new()\n\tray.FilterType = Enum.RaycastFilterType.Include\n\tray.FilterDescendantsInstances = supports\n\tray.IgnoreWater = true\n\tlocal seed = math.floor(startedAt * 1000) % 2147483647\n\tlocal random = Random.new(seed)\n\tlocal halfX = math.max(0, ground.Size.X * 0.5 - 55)\n\tlocal halfZ = math.max(0, ground.Size.Z * 0.5 - 55)\n\t-- A fixed 85-stud lattice keeps paths available across Town, plots, and\n\t-- every biome without scanning Workspace or creating a whole-map crowd.\n\tfor x = -halfX, halfX, 85 do\n\t\tfor z = -halfZ, halfZ, 85 do\n\t\t\tlocal world = ground.CFrame:PointToWorldSpace(Vector3.new(x, 0, z))\n\t\t\tlocal hit = workspace:Raycast(world + Vector3.new(0, 300, 0), Vector3.new(0, -600, 0), ray)\n\t\t\tif hit then\n\t\t\t\ttable.insert(paths, {\n\t\t\t\t\tid = #paths + 1,\n\t\t\t\t\tcenter = hit.Position + Vector3.new(0, random:NextNumber(6, 10), 0),\n\t\t\t\t\tradius = random:NextNumber(8, 17),\n\t\t\t\t\tphase = random:NextNumber(0, math.pi * 2),\n\t\t\t\t\tspeed = random:NextNumber(0.14, 0.25),\n\t\t\t\t\tscale = random:NextNumber(1.1, 1.55),\n\t\t\t\t\ttint = Color3.fromRGB(random:NextInteger(162, 202), 245, 255),\n\t\t\t\t})\n\t\t\tend\n\t\tend\n\tend\n\treturn paths\nend\n\nlocal function makeGhost(folder, path, now, density)\n\tlocal model = Instance.new(\"Model\")\n\tmodel.Name = \"FloatingGhost_\" .. path.id\n\tmodel:SetAttribute(\"WorldPathCenter\", path.center)\n\tlocal scale = path.scale\n\tlocal parts = {}\n\tlocal function add(name, size, position, transparency, face)\n\t\tlocal value = part(model, name, size * scale, CFrame.new(position * scale),\n\t\t\tface and Color3.fromRGB(20, 35, 55) or path.tint,\n\t\t\ttransparency, face and Enum.Material.SmoothPlastic or Enum.Material.Neon)\n\t\ttable.insert(parts, { value = value, transparency = transparency })\n\t\treturn value\n\tend\n\tlocal body = add(\"SheetBody\", Vector3.new(2.25, 2.7, 1.65), Vector3.new(0, -0.15, 0), 0.3)\n\tadd(\"RoundHead\", Vector3.new(2.55, 2.25, 1.85), Vector3.new(0, 1.1, 0), 0.2)\n\tadd(\"LeftWisp\", Vector3.new(0.85, 1.65, 0.95), Vector3.new(-0.7, -1.55, 0.12), 0.4)\n\tadd(\"CenterWisp\", Vector3.new(0.9, 2, 1), Vector3.new(0, -1.65, 0.2), 0.4)\n\tadd(\"RightWisp\", Vector3.new(0.85, 1.65, 0.95), Vector3.new(0.7, -1.55, 0.12), 0.4)\n\tadd(\"LeftEye\", Vector3.new(0.3, 0.48, 0.18), Vector3.new(-0.48, 1.3, -0.88), 0.08, true)\n\tadd(\"RightEye\", Vector3.new(0.3, 0.48, 0.18), Vector3.new(0.48, 1.3, -0.88), 0.08, true)\n\tadd(\"LittleMouth\", Vector3.new(0.25, 0.34, 0.14), Vector3.new(0, 0.7, -0.92), 0.1, true)\n\tmodel.WorldPivot = CFrame.new()\n\temitter(body, \"SpiritWisps\", 5 * density, true, path.tint)\n\tlocal sparkles = emitter(body, \"WanderingFireflies\", (PARTICLES_PER_GHOST - 5) * density, false, path.tint)\n\t-- Fade in after positioning; nothing flashes at the origin on creation.\n\tfor _, entry in ipairs(parts) do entry.value.Transparency = 1 end\n\tmodel:PivotTo(CFrame.new(path.center))\n\tmodel.Parent = folder\n\tsparkles:Emit(8)\n\treturn { model = model, path = path, parts = parts, bornAt = now, fading = true }\nend\n\nfunction SpiritNightEffects.Start(runtime, startedAt, isCurrent, context)\n\tcontext = context or {}\n\tlocal quality = context.qualityScale or 1\n\tlocal density = quality * (context.intensity or 1)\n\tlocal ghostLimit = math.max(4, math.floor(MAX_GHOSTS * quality))\n\tlocal nextSpiritAudio = 0\n\tlocal spiritAudioCount = 0\n\tlocal folder = Instance.new(\"Folder\")\n\tfolder.Name = \"SpiritNightWorld\"\n\tfolder:SetAttribute(\"GhostLimit\", ghostLimit)\n\tfolder:SetAttribute(\"MaximumParticleRate\", ghostLimit * PARTICLES_PER_GHOST * density)\n\tfolder.Parent = runtime\n\tlocal paths = worldPaths(startedAt)\n\tlocal ghosts = {}\n\tlocal heartbeat\n\tlocal destroying\n\tlocal stopped = false\n\tlocal elapsed = 0\n\tlocal selectionElapsed = SELECTION_STEP\n\n\tlocal function cleanup()\n\t\tif stopped then return end\n\t\tstopped = true\n\t\tif heartbeat then heartbeat:Disconnect() end\n\t\tif destroying then destroying:Disconnect() end\n\t\ttable.clear(ghosts)\n\t\tfolder:Destroy()\n\tend\n\n\tlocal function selectNearby(now)\n\t\tlocal viewer = viewerPosition()\n\t\tlocal ranked = {}\n\t\tfor _, path in ipairs(paths) do\n\t\t\t-- Hysteresis prevents churn when standing between two paths.\n\t\t\tlocal distance = (path.center - viewer).Magnitude\n\t\t\ttable.insert(ranked, { path = path, score = distance - (ghosts[path.id] and 18 or 0) })\n\t\tend\n\t\ttable.sort(ranked, function(a, b) return a.score < b.score end)\n\t\tlocal selected = {}\n\t\tfor i = 1, math.min(ghostLimit, #ranked) do\n\t\t\tif ranked[i].score < 340 then selected[ranked[i].path.id] = ranked[i].path end\n\t\tend\n\t\tfor id, ghost in pairs(ghosts) do\n\t\t\tif not selected[id] then\n\t\t\t\tghost.model:Destroy()\n\t\t\t\tghosts[id] = nil\n\t\t\tend\n\t\tend\n\t\tfor id, path in pairs(selected) do\n\t\t\tif not ghosts[id] then ghosts[id] = makeGhost(folder, path, now, density) end\n\t\tend\n\tend\n\n\tdestroying = runtime.Destroying:Connect(cleanup)\n\theartbeat = RunService.Heartbeat:Connect(function(delta)\n\t\tif stopped then return end\n\t\tif not runtime.Parent or not folder.Parent or not isCurrent() then\n\t\t\tcleanup()\n\t\t\treturn\n\t\tend\n\t\telapsed += delta\n\t\tselectionElapsed += delta\n\t\tif elapsed < UPDATE_STEP then return end\n\t\telapsed %= UPDATE_STEP\n\t\tlocal now = workspace:GetServerTimeNow()\n\t\tif selectionElapsed >= SELECTION_STEP then\n\t\t\tselectionElapsed = 0\n\t\t\tselectNearby(now)\n\t\tend\n\t\tlocal age = math.max(0, now - startedAt)\n\t\t-- Sound timing uses logical world paths even at Low visual quality.\n\t\tif context.audio and now >= nextSpiritAudio then\n\t\t\tnextSpiritAudio = now + 11\n\t\t\tlocal viewer, nearest, distance = viewerPosition(), nil, 220\n\t\t\tfor _, path in ipairs(paths) do\n\t\t\t\tlocal d = (path.center - viewer).Magnitude\n\t\t\t\tif d < distance then nearest = path; distance = d end\n\t\t\tend\n\t\t\tif nearest then\n\t\t\t\tspiritAudioCount += 1\n\t\t\t\tlocal theta = nearest.phase + age * nearest.speed\n\t\t\t\tlocal spiritPosition = nearest.center + Vector3.new(math.cos(theta)*nearest.radius, math.sin(age*1.3+nearest.phase)*1.15, math.sin(theta)*nearest.radius*0.7)\n\t\t\t\tcontext.audio:PlayCue(\"SpiritPass\", spiritPosition)\n\t\t\t\tif spiritAudioCount % 3 == 0 then context.audio:PlayCue(\"SpiritWhisper\", spiritPosition) end\n\t\t\tend\n\t\tend\n\t\tfor _, ghost in pairs(ghosts) do\n\t\t\tlocal path = ghost.path\n\t\t\tlocal theta = path.phase + age * path.speed\n\t\t\tlocal position = path.center + Vector3.new(\n\t\t\t\tmath.cos(theta) * path.radius,\n\t\t\t\tmath.sin(age * 1.3 + path.phase) * 1.15,\n\t\t\t\tmath.sin(theta) * path.radius * 0.7)\n\t\t\tlocal direction = Vector3.new(-math.sin(theta), 0, math.cos(theta) * 0.7)\n\t\t\tghost.model:PivotTo(CFrame.lookAt(position, position + direction)\n\t\t\t\t* CFrame.Angles(0, 0, math.sin(age * 0.9 + path.phase) * 0.09))\n\t\t\tif ghost.fading then\n\t\t\t\tlocal alpha = math.clamp((now - ghost.bornAt) / 0.65, 0, 1)\n\t\t\t\tfor _, entry in ipairs(ghost.parts) do\n\t\t\t\t\tentry.value.Transparency = 1 - (1 - entry.transparency) * alpha\n\t\t\t\tend\n\t\t\t\tghost.fading = alpha < 1\n\t\t\tend\n\t\tend\n\tend)\n\treturn cleanup\nend\n\nreturn SpiritNightEffects\n"}, {"path": ["StarterPlayer", "StarterPlayerScripts", "WeatherVisualController"], "class": "LocalScript", "source": "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Lighting = game:GetService(\"Lighting\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Players = game:GetService(\"Players\")\nlocal TweenService = game:GetService(\"TweenService\")\n\nlocal DEBUG_VISUALS = RunService:IsStudio()\nlocal TRANSITION = 2\nif DEBUG_VISUALS then print(\"[WeatherVisuals] Script starting\") end\nlocal state = ReplicatedStorage:WaitForChild(\"WeatherState\")\nlocal shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal definitions = require(shared:WaitForChild(\"EventDefinitions\"))\nlocal meteorShowerEffects = require(shared:WaitForChild(\"MeteorShowerEffects\"))\nlocal spiritNightEffects = require(shared:WaitForChild(\"SpiritNightEffects\"))\nlocal celestialEffects = require(shared:WaitForChild(\"WeatherCelestialEffects\"))\nlocal environmentEffects = require(shared:WaitForChild(\"WeatherEnvironmentEffects\"))\nlocal weatherAudio = require(shared:WaitForChild(\"WeatherAudioController\"))\nlocal qualitySettings = require(shared:WaitForChild(\"WeatherVFXQuality\"))\n\nlocal function color(r, g, b)\n\treturn Color3.fromRGB(r, g, b)\nend\n\n-- Every event has its own lighting recipe. Particle and sky details are added below.\nlocal presets = {\n\tSunnySkies = { clock = 13, brightness = 3.2, exposure = 0.16, fog = 100000, atmosphere = 0.1, tint = color(255, 244, 215), saturation = 0.16, bloom = 0.22, rays = 0.11, clouds = 0.06 },\n\tRainyDay = { clock = 15, brightness = 1.35, exposure = -0.18, fog = 530, atmosphere = 0.47, tint = color(173, 198, 225), saturation = -0.18, bloom = 0.08, rays = 0, clouds = 0.92, particles = \"Rain\" },\n\tThunderstorm = { clock = 18, brightness = 1, exposure = -0.22, fog = 750, fogStart = 0, atmosphere = 0.42, tint = color(118, 145, 183), saturation = -0.32, bloom = 0.15, rays = 0, clouds = 1, particles = \"HeavyRain\", extraParticles = \"WindStreaks\", loop = \"Lightning\" },\n\tSnowfall = { clock = 11, brightness = 2.1, exposure = 0.02, fog = 440, fogStart = 0, atmosphere = 0.47, tint = color(188, 223, 255), saturation = -0.34, bloom = 0.26, rays = 0.02, clouds = 0.75, particles = \"Snow\" },\n\tFoggy = { clock = 10, brightness = 1.45, exposure = -0.1, fog = 190, fogStart = 25, atmosphere = 0.55, tint = color(167, 187, 203), saturation = -0.48, bloom = 0.03, blur = 2, rays = 0, clouds = 0.76 },\n\tWindy = { clock = 14, brightness = 2, exposure = -0.02, fog = 850, atmosphere = 0.32, tint = color(207, 226, 217), saturation = 0.02, bloom = 0.08, rays = 0.02, clouds = 0.8, particles = \"Leaves\", extraParticles = \"WindStreaks\", loop = \"Wind\" },\n\tHeatwave = { clock = 14, brightness = 3.35, exposure = 0.28, fog = 480, atmosphere = 0.4, tint = color(255, 206, 145), saturation = 0.19, bloom = 0.38, blur = 0.7, rays = 0.14, clouds = 0.04, particles = \"Haze\" },\n\tAurora = { clock = 0, brightness = 1.1, exposure = -0.12, fog = 100000, atmosphere = 0.15, tint = color(164, 196, 244), saturation = 0.32, bloom = 0.5, rays = 0, clouds = 0.08, particles = \"Stars\", sky = \"Aurora\" },\n\tBloodMoon = { clock = 0, brightness = 0.7, exposure = -0.3, fog = 100000, fogStart = 0, atmosphere = 0.2, tint = color(211, 89, 103), saturation = 0.05, bloom = 0.3, rays = 0, clouds = 0.52, particles = \"Ash\", sky = \"BloodMoon\" },\n\tMeteorShower = { clock = 0, brightness = 1.05, exposure = -0.12, fog = 100000, atmosphere = 0.16, tint = color(159, 180, 237), saturation = 0.2, bloom = 0.45, rays = 0, clouds = 0.03, particles = \"Stars\", loop = \"Meteors\" },\n\tSpiritNight = { clock = 1, brightness = 1.1, exposure = -0.1, fog = 650, atmosphere = 0.30, tint = color(134, 219, 235), saturation = 0.24, bloom = 0.44, rays = 0, clouds = 0.25, particles = \"SpiritMist\", loop = \"Spirits\" },\n\tRainbow = { clock = 14, brightness = 3.15, exposure = 0.16, fog = 100000, atmosphere = 0.06, tint = color(255, 240, 254), saturation = 0.4, bloom = 0.34, rays = 0.09, clouds = 0.12, particles = \"Sparkles\", sky = \"Rainbow\" },\n\tChaos = { clock = 19, brightness = 2, exposure = 0.04, fog = 1200, atmosphere = 0.23, tint = color(255, 190, 230), saturation = 0.25, bloom = 0.5, rays = 0, clouds = 0.72, particles = \"Chaos\", loop = \"Chaos\" },\n\tInverted = { clock = 22, brightness = 1.7, exposure = 0.1, fog = 900, atmosphere = 0.24, tint = color(173, 255, 219), saturation = -0.65, bloom = 0.4, rays = 0, clouds = 0.6, particles = \"Inverted\" },\n\tNightmare = { clock = 0, brightness = 0.95, exposure = -0.22, fog = 380, atmosphere = 0.46, tint = color(166, 77, 127), saturation = -0.36, bloom = 0.25, rays = 0, clouds = 0.84, particles = \"Ash\", loop = \"Nightmare\" },\n\tVoid = { clock = 0, brightness = 0.9, exposure = -0.2, fog = 100000, atmosphere = 0.16, tint = color(129, 85, 204), saturation = -0.18, bloom = 0.59, blur = 0, rays = 0, clouds = 0.12, particles = \"Void\", sky = \"Void\" },\n\tGolden = { clock = 16, brightness = 2.8, exposure = 0.13, fog = 1600, atmosphere = 0.18, tint = color(255, 229, 164), saturation = 0.18, bloom = 0.4, rays = 0.16, clouds = 0.1, particles = \"Gold\" },\n\tAdminAbuse = { clock = 19, brightness = 2.1, exposure = 0.06, fog = 100000, atmosphere = 0.13, tint = color(255, 198, 247), saturation = 0.38, bloom = 0.52, rays = 0.06, clouds = 0.58, particles = \"Admin\", loop = \"Admin\" },\n}\n\n-- WeatherState uses the canonical IDs in EventDefinitions. Accept the older\n-- underscored spellings as input without changing the server's event contract.\nlocal aliases = {\n\tSunny_Skies = \"SunnySkies\", Rainy_Day = \"RainyDay\", Blood_Moon = \"BloodMoon\",\n\tMeteor_Shower = \"MeteorShower\", Spirit_Night = \"SpiritNight\", Admin_Abuse = \"AdminAbuse\",\n}\n\nlocal lightingProperties = { \"Brightness\", \"ClockTime\", \"ExposureCompensation\", \"FogStart\", \"FogEnd\", \"FogColor\", \"Ambient\", \"OutdoorAmbient\", \"ColorShift_Top\", \"ColorShift_Bottom\" }\nlocal effectProperties = {\n\tAtmosphere = { \"Density\", \"Color\", \"Decay\", \"Haze\", \"Glare\", \"Offset\" },\n\tClouds = { \"Cover\", \"Density\", \"Color\", \"Enabled\" },\n\tColorCorrectionEffect = { \"Brightness\", \"Contrast\", \"Saturation\", \"TintColor\", \"Enabled\" },\n\tBloomEffect = { \"Intensity\", \"Size\", \"Threshold\", \"Enabled\" },\n\tSunRaysEffect = { \"Intensity\", \"Spread\", \"Enabled\" },\n\tDepthOfFieldEffect = { \"FarIntensity\", \"FocusDistance\", \"InFocusRadius\", \"NearIntensity\", \"Enabled\" },\n\tBlurEffect = { \"Size\", \"Enabled\" },\n}\nlocal originalWind = workspace.GlobalWind\nlocal original = {}\nfor _, property in ipairs(lightingProperties) do original[property] = Lighting[property] end\n-- The folder is a client-local index of managed effects. Roblox renders\n-- Atmosphere/post effects under Lighting and Clouds under Terrain, so the live\n-- instances cannot be placed inside this folder without disabling them.\nlocal visualFolder = Lighting:FindFirstChild(\"AK_WeatherVisuals\")\nif not visualFolder then\n\tvisualFolder = Instance.new(\"Folder\")\n\tvisualFolder.Name = \"AK_WeatherVisuals\"\n\tvisualFolder.Parent = Lighting\nend\nlocal function indexEffect(className, effect)\n\tlocal reference = visualFolder:FindFirstChild(className)\n\tif not reference or not reference:IsA(\"ObjectValue\") then\n\t\treference = Instance.new(\"ObjectValue\")\n\t\treference.Name = className\n\t\treference.Parent = visualFolder\n\tend\n\treference.Value = effect\nend\nlocal effects = {}\nlocal initialEffects = {}\nlocal createdEffects = {}\nlocal terrain = workspace.Terrain\nlocal requiredEffects = { \"Atmosphere\", \"ColorCorrectionEffect\", \"BloomEffect\", \"BlurEffect\", \"SunRaysEffect\", \"Clouds\" }\nlocal effectLabels = {\n\tColorCorrectionEffect = \"ColorCorrection\", BloomEffect = \"Bloom\",\n\tBlurEffect = \"Blur\", SunRaysEffect = \"SunRays\",\n}\n\nlocal function ensureEffect(className, parent)\n\tlocal effect = effects[className]\n\tif effect and effect.Parent == parent then\n\t\tif DEBUG_VISUALS then print(\"[WeatherVisuals] \" .. (effectLabels[className] or className) .. \" ready\") end\n\t\treturn effect\n\tend\n\teffect = parent:FindFirstChildOfClass(className)\n\tif effect and not initialEffects[className] then\n\t\tlocal snapshot = {}\n\t\tfor _, property in ipairs(effectProperties[className]) do snapshot[property] = effect[property] end\n\t\tinitialEffects[className] = snapshot\n\t\tcreatedEffects[className] = nil\n\tend\n\tif not effect then\n\t\tlocal ok, result = pcall(Instance.new, className)\n\t\tif not ok then\n\t\t\twarn(\"[WeatherVisuals] Cannot create \" .. className .. \": \" .. tostring(result))\n\t\t\treturn nil\n\t\tend\n\t\teffect = result\n\t\teffect.Name = \"AK_Weather\" .. className\n\t\tif effect:IsA(\"PostEffect\") then effect.Enabled = false end\n\t\tif className == \"Atmosphere\" then\n\t\t\teffect.Density = 0\n\t\t\teffect.Haze = 0\n\t\t\teffect.Glare = 0\n\t\telseif className == \"Clouds\" then\n\t\t\teffect.Cover = 0\n\t\t\teffect.Enabled = false\n\t\tend\n\t\teffect.Parent = parent\n\t\tcreatedEffects[className] = true\n\tend\n\teffects[className] = effect\n\tindexEffect(className, effect)\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] \" .. (effectLabels[className] or className) .. \" ready\") end\n\treturn effect\nend\n\n-- Capture the real map appearance before any weather instance is created.\nfor className, properties in pairs(effectProperties) do\n\tlocal parent = className == \"Clouds\" and terrain or Lighting\n\tlocal effect = parent:FindFirstChildOfClass(className)\n\tif effect then\n\t\tlocal snapshot = {}\n\t\tfor _, property in ipairs(properties) do snapshot[property] = effect[property] end\n\t\tinitialEffects[className] = snapshot\n\t\teffects[className] = effect\n\t\tindexEffect(className, effect)\n\tend\nend\n\nlocal generation = 0\nlocal activeKey\nlocal activeEventId\nlocal runtime\nlocal followConnection\nlocal moduleCleanups = {}\nlocal audioSession\nlocal runningTweens = {}\nlocal refreshQueued = false\n\n\nlocal function trackTween(instance, properties, seconds)\n\tif not instance then\n\t\twarn(\"[WeatherVisuals] Cannot tween a missing visual instance\")\n\t\treturn nil\n\tend\n\tlocal ok, animation = pcall(TweenService.Create, TweenService, instance, TweenInfo.new(seconds or TRANSITION, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), properties)\n\tif not ok then\n\t\twarn(\"[WeatherVisuals] Tween failed for \" .. instance.Name .. \": \" .. tostring(animation))\n\t\t-- Keep the preset visible even if a property cannot be tweened in Studio.\n\t\tfor property, value in pairs(properties) do\n\t\t\tlocal setOk, setError = pcall(function() instance[property] = value end)\n\t\t\tif not setOk then warn(\"[WeatherVisuals] Cannot set \" .. instance.Name .. \".\" .. property .. \": \" .. tostring(setError)) end\n\t\tend\n\t\treturn nil\n\tend\n\ttable.insert(runningTweens, animation)\n\tanimation.Completed:Connect(function()\n\t\tlocal index = table.find(runningTweens, animation)\n\t\tif index then table.remove(runningTweens, index) end\n\tend)\n\tanimation:Play()\n\treturn animation\nend\n\nlocal function cancelTweens()\n\t-- Cancel may fire Completed synchronously; swap the list first so its\n\t-- removal callback cannot skip every other active tween.\n\tlocal oldTweens = runningTweens\n\trunningTweens = {}\n\tfor _, animation in ipairs(oldTweens) do animation:Cancel() end\nend\n\nlocal function restoreOriginal(token)\n\ttrackTween(Lighting, original)\n\ttrackTween(workspace, { GlobalWind = originalWind })\n\tfor className, effect in pairs(effects) do\n\t\tlocal snapshot = initialEffects[className]\n\t\tif snapshot then\n\t\t\tlocal numericAndColor = {}\n\t\t\tfor property, value in pairs(snapshot) do\n\t\t\t\tif property ~= \"Enabled\" then numericAndColor[property] = value end\n\t\t\tend\n\t\t\ttrackTween(effect, numericAndColor)\n\t\t\tif snapshot.Enabled ~= nil then\n\t\t\t\ttask.delay(TRANSITION, function()\n\t\t\t\t\tif token == generation then effect.Enabled = snapshot.Enabled end\n\t\t\t\tend)\n\t\t\tend\n\t\telse\n\t\t\t-- Newly created effects fade to neutral, then leave Lighting entirely.\n\t\t\tif className == \"Atmosphere\" then trackTween(effect, { Density = 0, Haze = 0, Glare = 0 }) end\n\t\t\tif className == \"Clouds\" then trackTween(effect, { Cover = 0 }) end\n\t\t\tif className == \"ColorCorrectionEffect\" then trackTween(effect, { Brightness = 0, Contrast = 0, Saturation = 0, TintColor = Color3.new(1, 1, 1) }) end\n\t\t\tif className == \"BloomEffect\" then trackTween(effect, { Intensity = 0 }) end\n\t\t\tif className == \"SunRaysEffect\" then trackTween(effect, { Intensity = 0 }) end\n\t\t\tif className == \"BlurEffect\" then trackTween(effect, { Size = 0 }) end\n\t\tend\n\tend\n\ttask.delay(TRANSITION + 0.05, function()\n\t\tif token ~= generation then return end\n\t\tfor className in pairs(createdEffects) do\n\t\t\tlocal effect = effects[className]\n\t\t\tif effect then effect:Destroy() end\n\t\t\teffects[className] = nil\n\t\t\tindexEffect(className, nil)\n\t\tend\n\tend)\nend\n\nlocal function ensureEffects()\n\tlocal ready = true\n\tfor _, className in ipairs(requiredEffects) do\n\t\tlocal parent = className == \"Clouds\" and terrain or Lighting\n\t\tif not ensureEffect(className, parent) then ready = false end\n\tend\n\treturn ready\nend\n\nlocal function clearEvent(restore)\n\tgeneration += 1\n\tfor _, cleanup in ipairs(moduleCleanups) do cleanup() end\n\ttable.clear(moduleCleanups)\n\tif audioSession then\n\t\tif restore then audioSession:StopAudio(1.2) else audioSession:CleanupAudio() end\n\t\taudioSession = nil\n\tend\n\tcancelTweens()\n\tif followConnection then followConnection:Disconnect(); followConnection = nil end\n\tif runtime then runtime:Destroy(); runtime = nil end\n\tif DEBUG_VISUALS and activeEventId then print(\"[WeatherVisuals] Clearing previous effects\") end\n\tif DEBUG_VISUALS and activeEventId then print(\"[WeatherVisuals] Clearing \" .. activeEventId) end\n\tif DEBUG_VISUALS and restore and activeEventId then print(\"[WeatherVisuals] Restoring defaults\") end\n\tactiveKey = nil\n\tactiveEventId = nil\n\tif restore then restoreOriginal(generation) end\nend\n\nlocal function makePart(name, parent, size, tint, transparency)\n\tlocal part = Instance.new(\"Part\")\n\tpart.Name = name\n\tpart.Anchored = true\n\tpart.CanCollide = false\n\tpart.CanTouch = false\n\tpart.CanQuery = false\n\tpart.CastShadow = false\n\tpart.Material = Enum.Material.Neon\n\tpart.Color = tint\n\tpart.Transparency = transparency or 0\n\tpart.Size = size\n\tpart.Parent = parent\n\treturn part\nend\n\nlocal particleStyles = {\n\tRain = { rate = 380, speed = NumberRange.new(55, 70), life = NumberRange.new(0.7, 1), size = 0.95, squash = 2.5, color = color(192, 217, 247), spread = 7, acceleration = Vector3.new(3, -55, 0) },\n\tHeavyRain = { rate = 560, speed = NumberRange.new(75, 95), life = NumberRange.new(0.65, 0.95), size = 1.4, squash = 3, color = color(202, 224, 255), spread = 12, acceleration = Vector3.new(12, -75, 0) },\n\tSnow = { rate = 210, speed = NumberRange.new(14, 22), life = NumberRange.new(2.2, 3.4), size = 0.42, color = color(244, 250, 255), spread = 35, acceleration = Vector3.new(5, -4, 2) },\n\tLeaves = { rate = 95, speed = NumberRange.new(35, 55), life = NumberRange.new(1.1, 1.8), size = 0.43, color = color(167, 197, 105), spread = 20, direction = Enum.NormalId.Right, acceleration = Vector3.new(35, 1, 5) },\n\tWindStreaks = { rate = 105, speed = NumberRange.new(70, 105), life = NumberRange.new(0.55, 0.95), size = 0.38, squash = 2.8, color = color(212, 235, 246), spread = 12, direction = Enum.NormalId.Right, acceleration = Vector3.new(30, 0, 0) },\n}\n\nlocal function addParticles(styleName, rig, context)\n\tlocal style = particleStyles[styleName]\n\tif not style then return end\n\tlocal emitter = Instance.new(\"ParticleEmitter\")\n\tlocal isRain = styleName == \"Rain\" or styleName == \"HeavyRain\"\n\temitter.Name = styleName .. \"Particles\"\n\temitter.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n\temitter.Shape = Enum.ParticleEmitterShape.Box\n\temitter.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume\n\temitter.EmissionDirection = style.direction or Enum.NormalId.Bottom\n\temitter.Rate = style.rate * context.qualityScale * context.intensity\n\temitter.Lifetime = style.life\n\temitter.Speed = style.speed\n\temitter.SpreadAngle = Vector2.new(style.spread, style.spread)\n\temitter.Acceleration = style.acceleration\n\temitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, style.size, styleName == \"Snow\" and 0.2 or 0), NumberSequenceKeypoint.new(1, 0) })\n\tif isRain then\n\t\t-- Keep drops readable through the playable height; fade below the floor.\n\t\temitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, style.size), NumberSequenceKeypoint.new(0.7, style.size), NumberSequenceKeypoint.new(1, 0) })\n\tend\n\tif styleName == \"Snow\" or styleName == \"Leaves\" then\n\t\temitter.Rotation = NumberRange.new(0, 360)\n\t\temitter.RotSpeed = NumberRange.new(-75, 75)\n\tend\n\tif style.squash then emitter.Squash = NumberSequence.new(style.squash) end\n\tif style.squash then emitter.Orientation = Enum.ParticleOrientation.VelocityParallel end\n\temitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.08), NumberSequenceKeypoint.new(0.8, 0.22), NumberSequenceKeypoint.new(1, 1) })\n\temitter.Color = ColorSequence.new(style.color)\n\temitter.LightEmission = isRain and 0.3 or 0.55\n\temitter.LightInfluence = isRain and 0 or 0.15\n\temitter.LockedToPart = false\n\temitter.Enabled = true\n\temitter.Parent = rig\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Created \" .. styleName .. \" effect; enabled=\" .. tostring(emitter.Enabled) .. \" rate=\" .. tostring(emitter.Rate)) end\nend\n\nlocal function applyEvent(eventId, key)\n\tlocal preset = presets[eventId]\n\tif not preset or not definitions[eventId] then return end\n\tclearEvent(false)\n\tif not ensureEffects() then\n\t\twarn(\"[WeatherVisuals] Preset \" .. eventId .. \" skipped: required visual effect missing\")\n\t\treturn\n\tend\n\tactiveKey = key\n\tactiveEventId = eventId\n\tlocal token = generation\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Applying preset: \" .. eventId) end\n\truntime = Instance.new(\"Folder\")\n\truntime.Name = \"WeatherWorldEffects\"\n\truntime:SetAttribute(\"EventId\", eventId)\n\truntime.Parent = workspace\n\tlocal context = qualitySettings.Resolve()\n\tcontext.effects = effects\n\truntime:SetAttribute(\"QualityScale\", context.qualityScale)\n\truntime:SetAttribute(\"EventIntensity\", context.intensity)\n\tlocal startedAt = state:GetAttribute(\"StartedAt\")\n\tlocal windSpeed = ({SunnySkies=5,RainyDay=13,Thunderstorm=35,Snowfall=10,Foggy=3,Windy=45,Heatwave=8,Chaos=22,AdminAbuse=30})[eventId] or 5\n\ttrackTween(workspace, { GlobalWind = Vector3.new(windSpeed, 0, windSpeed * 0.25) })\n\taudioSession = weatherAudio.Start(eventId, startedAt, runtime)\n\tcontext.audio = audioSession\n\t-- Nearby precipitation uses fixed world cells selected by character location.\n\t-- Turning/tilting the camera never translates or rotates an environmental VFX.\n\tlocal updatePrecipitation\n\tlocal precipitation = { RainyDay = {\"Rain\"}, Thunderstorm = {\"HeavyRain\", \"WindStreaks\"}, Snowfall = {\"Snow\"}, Windy = {\"Leaves\", \"WindStreaks\"} }\n\tif precipitation[eventId] then\n\t\tlocal rig = makePart(\"WeatherEmitterRig\", runtime, Vector3.new(76, 2, 76), Color3.new(1,1,1), 1)\n\t\tfor _, name in ipairs(precipitation[eventId]) do addParticles(name, rig, context) end\n\t\tupdatePrecipitation = function()\n\t\t\tlocal player = Players.LocalPlayer\n\t\t\tlocal root = player and player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\t\tif root and rig.Parent then\n\t\t\t\tlocal p = root.Position\n\t\t\t\trig.Position = Vector3.new(math.floor(p.X / 24 + 0.5) * 24, math.floor(p.Y / 12) * 12 + 28, math.floor(p.Z / 24 + 0.5) * 24)\n\t\t\tend\n\t\tend\n\t\tupdatePrecipitation()\n\tend\n\t-- One bounded presentation tick for moving clouds and subtle supplemental\n\t-- pulses. Never moves an environmental object from the camera transform.\n\tlocal motionElapsed = 0\n\tlocal appliedAt = os.clock()\n\tfollowConnection = RunService.Heartbeat:Connect(function(delta)\n\t\tmotionElapsed += delta\n\t\tif motionElapsed < 0.2 then return end\n\t\tmotionElapsed = 0\n\t\tif updatePrecipitation then updatePrecipitation() end\n\t\tif os.clock() - appliedAt < TRANSITION then return end\n\t\tlocal age = workspace:GetServerTimeNow() - startedAt\n\t\tlocal gust = 1 + math.sin(age * 0.5) * ((eventId == \"Windy\" or eventId == \"Thunderstorm\") and 0.25 or 0.1)\n\t\tworkspace.GlobalWind = Vector3.new(windSpeed * gust, 0, windSpeed * 0.25)\n\t\tif eventId == \"Chaos\" or eventId == \"AdminAbuse\" then\n\t\t\teffects.ColorCorrectionEffect.TintColor = Color3.fromHSV((age * 0.025) % 1, eventId == \"AdminAbuse\" and 0.23 or 0.3, 1)\n\t\telseif eventId == \"BloodMoon\" then\n\t\t\tLighting.Brightness = preset.brightness + math.sin(age * 0.5) * 0.06\n\t\telseif eventId == \"Nightmare\" then\n\t\t\teffects.ColorCorrectionEffect.Brightness = -0.015 * (0.5 + math.sin(age * 0.36) * 0.5)\n\t\telseif eventId == \"Heatwave\" then\n\t\t\teffects.BlurEffect.Size = 0.55 + math.sin(age * 0.7) * 0.18\n\t\tend\n\tend)\n\tlocal tint = preset.tint\n\ttrackTween(Lighting, {\n\t\tClockTime = preset.clock, Brightness = preset.brightness,\n\t\tExposureCompensation = 